fn reverse_string(s: &str) -> String {
    s.chars().rev().collect()
}

fn is_palindrome(s: &str) -> bool {
    let cleaned: String = s.chars().filter(|c| c.is_alphanumeric()).flat_map(|c| c.to_lowercase()).collect();
    cleaned == reverse_string(&cleaned)
}

fn reverse_nth_word(text: &str, n: usize) -> Option<String> {
    let word = text.split_whitespace().nth(n)?;
    Some(reverse_string(word))
}

#[derive(Debug)]
enum ParseError {
    Incomplete(String),
    UnknownVerb(String),
    BadIndex(String),
    NoWord(usize),
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            ParseError::Incomplete(line) => write!(f, "incomplete command: {:?}", line),
            ParseError::UnknownVerb(verb) => write!(f, "unknown verb: {:?}", verb),
            ParseError::BadIndex(idx) => write!(f, "not a word index: {:?}", idx),
            ParseError::NoWord(n) => write!(f, "text has no word at position {}", n),
        }
    }
}

enum Command<'a> {
    Rev(&'a str),
    Word(usize, &'a str),
    Pal(&'a str),
}

fn parse_command(line: &str) -> Result<Command<'_>, ParseError> {
    let (verb, rest) = line.split_once(' ').ok_or_else(|| ParseError::Incomplete(line.to_string()))?;
    match verb {
        "rev" => Ok(Command::Rev(rest)),
        "word" => {
            let (idx, text) = rest.split_once(' ').ok_or_else(|| ParseError::Incomplete(line.to_string()))?;
            let n = idx.parse::<usize>().map_err(|_| ParseError::BadIndex(idx.to_string()))?;
            Ok(Command::Word(n, text))
        }
        "pal" => Ok(Command::Pal(rest)),
        other => Err(ParseError::UnknownVerb(other.to_string())),
    }
}

fn execute(line: &str) -> Result<String, ParseError> {
    match parse_command(line)? {
        Command::Rev(text) => Ok(reverse_string(text)),
        Command::Word(n, text) => {
            let reversed = reverse_nth_word(text, n).ok_or(ParseError::NoWord(n))?;
            Ok(reversed)
        }
        Command::Pal(text) => Ok(if is_palindrome(text) { "yes".to_string() } else { "no".to_string() }),
    }
}

fn run_script(script: &str) -> Result<Vec<String>, ParseError> {
    let mut results = Vec::new();
    for line in script.lines().map(str::trim).filter(|l| !l.is_empty()) {
        results.push(execute(line)?);
    }
    Ok(results)
}

fn main() -> Result<(), ParseError> {
    let script = "rev hello\n\
                  rev Rust\n\
                  word 1 never odd or even\n\
                  pal Never odd or even!\n\
                  pal not a palindrome";
    let outputs = run_script(script)?;
    for (line, out) in script.lines().map(str::trim).filter(|l| !l.is_empty()).zip(&outputs) {
        println!("{:30} -> {}", line, out);
    }
    Ok(())
}

