use std::num::ParseIntError;

/// Returns the largest value in `numbers`, or `None` when the slice is empty.
fn find_max(numbers: &[i32]) -> Option<i32> {
    let (first, rest) = numbers.split_first()?;
    let mut best = *first;
    for value in rest {
        if *value > best {
            best = *value;
        }
    }
    Some(best)
}

/// Returns the smallest value in `numbers`, or `None` when the slice is empty.
fn find_min(numbers: &[i32]) -> Option<i32> {
    let (first, rest) = numbers.split_first()?;
    let mut best = *first;
    for value in rest {
        if *value < best {
            best = *value;
        }
    }
    Some(best)
}

/// Distance between the extremes of `numbers`.
fn range_of(numbers: &[i32]) -> Option<i32> {
    let high = find_max(numbers)?;
    let low = find_min(numbers)?;
    Some(high - low)
}

/// Parses a comma-separated row of integers.
fn parse_row(line: &str) -> Result<Vec<i32>, String> {
    let mut values = Vec::new();
    for field in line.split(',') {
        let text = field.trim();
        let value: i32 = text
            .parse()
            .map_err(|e: ParseIntError| format!("bad field {:?}: {}", text, e))?;
        values.push(value);
    }
    Ok(values)
}

/// One human-readable line describing the extremes of a parsed row.
fn summarize(line: &str) -> Result<String, String> {
    let values = parse_row(line)?;
    let max = find_max(&values).ok_or_else(|| format!("row {:?} has no values", line))?;
    let span = range_of(&values).ok_or_else(|| format!("row {:?} has no values", line))?;
    Ok(format!("{:<20} max={:>4} span={:>4}\n", line, max, span))
}

/// The largest value across every row, or `None` if no row holds a value.
fn overall_max(lines: &[&str]) -> Result<Option<i32>, String> {
    let mut best: Option<i32> = None;
    for line in lines {
        let values = parse_row(line)?;
        if let Some(candidate) = find_max(&values) {
            best = Some(match best {
                Some(current) => current.max(candidate),
                None => candidate,
            });
        }
    }
    Ok(best)
}

fn report(lines: &[&str]) -> Result<String, String> {
    let mut text = String::new();
    for line in lines {
        text.push_str(&summarize(line)?);
    }
    Ok(text)
}

fn main() -> Result<(), String> {
    let rows = ["1, 5, 2, 8", "-3, -3, -3", "10, 0, 7, 7, 42"];
    print!("{}", report(&rows)?);
    match overall_max(&rows)? {
        Some(max) => println!("overall maximum: {}", max),
        None => println!("overall maximum: none"),
    }
    Ok(())
}

