use std::env;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum FactError {
    Parse(ParseIntError),
    Overflow(u64),
    BadRange { n: u64, k: u64 },
}

impl fmt::Display for FactError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            FactError::Parse(e) => write!(f, "invalid number: {}", e),
            FactError::Overflow(n) => write!(f, "{}! does not fit in u64", n),
            FactError::BadRange { n, k } => write!(f, "k={} exceeds n={}", k, n),
        }
    }
}

impl From<ParseIntError> for FactError {
    fn from(e: ParseIntError) -> Self {
        FactError::Parse(e)
    }
}

fn factorial(n: u64) -> u64 {
    (1..=n).product()
}

fn checked_factorial(n: u64) -> Result<u64, FactError> {
    let mut acc: u64 = 1;
    for i in 1..=n {
        acc = acc.checked_mul(i).ok_or(FactError::Overflow(n))?;
    }
    Ok(acc)
}

fn parse_n(text: &str) -> Result<u64, FactError> {
    let n: u64 = text.trim().parse()?;
    Ok(n)
}

fn binomial(n: u64, k: u64) -> Result<u64, FactError> {
    if k > n {
        return Err(FactError::BadRange { n, k });
    }
    let numerator = checked_factorial(n)?;
    let lower = checked_factorial(k)?;
    let upper = checked_factorial(n - k)?;
    let denominator = lower.checked_mul(upper).ok_or(FactError::Overflow(n))?;
    Ok(numerator / denominator)
}

fn format_row(n: u64) -> Result<String, FactError> {
    let mut parts = Vec::new();
    for k in 0..=n {
        parts.push(binomial(n, k)?.to_string());
    }
    Ok(parts.join(" "))
}

fn report(text: &str) -> Result<String, FactError> {
    let n = parse_n(text)?;
    let exact = checked_factorial(n)?;
    let row = format_row(n)?;
    Ok(format!("{}! = {} | row {}: {}", n, exact, n, row))
}

fn main() -> Result<(), FactError> {
    let args: Vec<String> = env::args().skip(1).collect();
    let inputs: Vec<String> = if args.is_empty() {
        vec!["0".to_string(), "5".to_string(), "10".to_string()]
    } else {
        args
    };
    for text in &inputs {
        println!("{}", report(text)?);
    }
    let biggest = parse_n(inputs.last().unwrap())?;
    println!("unchecked factorial({}) = {}", biggest, factorial(biggest));
    Ok(())
}

