use std::env;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum FactError {
    Parse(ParseIntError),
    Overflow(u64),
    BadRange { n: u64, k: u64 },
}

impl fmt::Display for FactError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            FactError::Parse(e) => write!(f, "invalid number: {}", e),
            FactError::Overflow(n) => write!(f, "{}! does not fit in u64", n),
            FactError::BadRange { n, k } => write!(f, "k={} exceeds n={}", k, n),
        }
    }
}

impl From<ParseIntError> for FactError {
    fn from(e: ParseIntError) -> Self {
        FactError::Parse(e)
    }
}

fn factorial(n: u64) -> u64 {
    (1..=n).product()
}

fn checked_factorial(n: u64) -> Result<u64, FactError> {
    let mut acc: u64 = 1;
    for i in 1..=n {
        acc = match acc.checked_mul(i).ok_or(FactError::Overflow(n)) { Ok(v) => v, Err(e) => return Err(e.into()) };
    }
    Ok(acc)
}

fn parse_n(text: &str) -> Result<u64, FactError> {
    let n: u64 = match text.trim().parse() { Ok(v) => v, Err(e) => return Err(e.into()) };
    Ok(n)
}

fn binomial(n: u64, k: u64) -> Result<u64, FactError> {
    if k > n {
        return Err(FactError::BadRange { n, k });
    }
    let numerator = match checked_factorial(n) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let lower = match checked_factorial(k) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let upper = match checked_factorial(n - k) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let denominator = match lower.checked_mul(upper).ok_or(FactError::Overflow(n)) { Ok(v) => v, Err(e) => return Err(e.into()) };
    Ok(numerator / denominator)
}

fn format_row(n: u64) -> Result<String, FactError> {
    let mut parts = Vec::new();
    for k in 0..=n {
        parts.push(match binomial(n, k) { Ok(v) => v, Err(e) => return Err(e.into()) }.to_string());
    }
    Ok(parts.join(" "))
}

fn report(text: &str) -> Result<String, FactError> {
    let n = match parse_n(text) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let exact = match checked_factorial(n) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let row = match format_row(n) { Ok(v) => v, Err(e) => return Err(e.into()) };
    Ok(format!("{}! = {} | row {}: {}", n, exact, n, row))
}

fn main() -> Result<(), FactError> {
    let args: Vec<String> = env::args().skip(1).collect();
    let inputs: Vec<String> = if args.is_empty() {
        vec!["0".to_string(), "5".to_string(), "10".to_string()]
    } else {
        args
    };
    for text in &inputs {
        println!("{}", match report(text) { Ok(v) => v, Err(e) => return Err(e.into()) });
    }
    let biggest = match parse_n(inputs.last().unwrap()) { Ok(v) => v, Err(e) => return Err(e.into()) };
    println!("unchecked factorial({}) = {}", biggest, factorial(biggest));
    Ok(())
}

