use std::env;
use std::fs;
use std::io;

#[derive(Debug)]
enum AppError {
    Usage,
    Io(io::Error),
    BadWord(String),
    NoWords,
}

impl From<io::Error> for AppError {
    fn from(e: io::Error) -> Self {
        AppError::Io(e)
    }
}

fn count_word_occurrences(text: &str, word: &str) -> usize {
    let target = word.to_lowercase();
    if target.is_empty() {
        return 0;
    }
    text.split(|c: char| !c.is_alphanumeric() && c != '\'')
        .filter(|token| token.to_lowercase() == target)
        .count()
}

fn validate_word(entry: &str) -> Result<String, AppError> {
    if !entry.chars().all(|c| c.is_alphanumeric() || c == '\'') {
        return Err(AppError::BadWord(entry.to_string()));
    }
    Ok(entry.to_string())
}

fn load_words(path: &str) -> Result<Vec<String>, AppError> {
    let raw = fs::read_to_string(path)?;
    let mut words = Vec::new();
    for line in raw.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        words.push(validate_word(trimmed)?);
    }
    if words.is_empty() {
        return Err(AppError::NoWords);
    }
    Ok(words)
}

fn build_report(text: &str, words: &[String]) -> String {
    let mut out = String::new();
    let mut total = 0usize;
    for word in words {
        let count = count_word_occurrences(text, word);
        total += count;
        out.push_str(&format!("{:<20}{}\n", word, count));
    }
    out.push_str(&format!("{:<20}{}\n", "TOTAL", total));
    out
}

fn run() -> Result<(), AppError> {
    let mut args = env::args().skip(1);
    let text_path = args.next().ok_or(AppError::Usage)?;
    let words_path = args.next().ok_or(AppError::Usage)?;
    let text = fs::read_to_string(&text_path)?;
    let words = load_words(&words_path)?;
    print!("{}", build_report(&text, &words));
    Ok(())
}

fn describe(err: &AppError) -> String {
    match err {
        AppError::Usage => "usage: wordcount <text-file> <word-list-file>".to_string(),
        AppError::Io(e) => format!("i/o error: {}", e),
        AppError::BadWord(w) => format!("invalid word entry: {:?}", w),
        AppError::NoWords => "word list contains no entries".to_string(),
    }
}

fn main() {
    if let Err(e) = run() {
        eprintln!("{}", describe(&e));
        std::process::exit(1);
    }
}

