    let records = parse_records(text)?;
    let average = average_score(&records)?;
    let mut out = String::new();
    for record in &records {
        let state = if record.active { "active" } else { "inactive" };
        writeln!(out, "#{} {:<8} {:<8} {:.2}", record.id, record.name, state, record.score)
            .map_err(|e| e.to_string())?;
    }
    write!(out, "average score: {:.2}", average).map_err(|e| e.to_string())?;
    Ok(out)
}

fn main() -> Result<()> {
