use std::fmt::Write as _;

fn distance_2d(p1: (f64, f64), p2: (f64, f64)) -> f64 {
    let dx = p2.0 - p1.0;
    let dy = p2.1 - p1.1;
    (dx * dx + dy * dy).sqrt()
}

fn parse_coord(token: &str) -> Result<f64, String> {
    let text = token.trim();
    let value: f64 = match text
        .parse()
        .map_err(|_| format!("'{}' is not a number", text)) { Ok(v) => v, Err(e) => return Err(e.into()) };
    if value.is_finite() {
        Ok(value)
    } else {
        Err(format!("'{}' is not a finite coordinate", text))
    }
}

fn parse_point(spec: &str) -> Result<(f64, f64), String> {
    let mut parts = spec.split(',');
    let raw_x = match parts.next().ok_or_else(|| format!("missing x in '{}'", spec)) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let x = match parse_coord(raw_x) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let raw_y = match parts.next().ok_or_else(|| format!("missing y in '{}'", spec)) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let y = match parse_coord(raw_y) { Ok(v) => v, Err(e) => return Err(e.into()) };
    match parts.next() {
        Some(extra) => Err(format!("unexpected extra coordinate '{}'", extra.trim())),
        None => Ok((x, y)),
    }
}

fn parse_path(spec: &str) -> Result<Vec<(f64, f64)>, String> {
    let mut points = Vec::new();
    for chunk in spec.split(';').filter(|c| !c.trim().is_empty()) {
        points.push(match parse_point(chunk) { Ok(v) => v, Err(e) => return Err(e.into()) });
    }
    Ok(points)
}

fn path_length(points: &[(f64, f64)]) -> f64 {
    points.windows(2).map(|w| distance_2d(w[0], w[1])).sum()
}

fn centroid(points: &[(f64, f64)]) -> Result<(f64, f64), String> {
    if points.is_empty() {
        return Err("path has no points".to_string());
    }
    let mut sum = (0.0, 0.0);
    for p in points {
        sum.0 += p.0;
        sum.1 += p.1;
    }
    let n = points.len() as f64;
    Ok((sum.0 / n, sum.1 / n))
}

fn farthest_from_centroid(points: &[(f64, f64)]) -> Result<(usize, f64), String> {
    let center = match centroid(points) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let mut best = (0usize, 0.0);
    for (i, p) in points.iter().enumerate() {
        let d = distance_2d(*p, center);
        if d > best.1 {
            best = (i, d);
        }
    }
    Ok(best)
}

fn format_report(spec: &str) -> Result<String, String> {
    let points = match parse_path(spec) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let center = match centroid(&points) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let (idx, radius) = match farthest_from_centroid(&points) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let mut out = String::new();
    match writeln!(out, "points: {}", points.len()).map_err(|e| e.to_string()) { Ok(v) => v, Err(e) => return Err(e.into()) };
    match writeln!(out, "length: {:.4}", path_length(&points)).map_err(|e| e.to_string()) { Ok(v) => v, Err(e) => return Err(e.into()) };
    match writeln!(out, "centroid: ({:.4}, {:.4})", center.0, center.1).map_err(|e| e.to_string()) { Ok(v) => v, Err(e) => return Err(e.into()) };
    match write!(out, "farthest point #{} at {:.4}", idx, radius).map_err(|e| e.to_string()) { Ok(v) => v, Err(e) => return Err(e.into()) };
    Ok(out)
}

fn main() -> Result<(), String> {
    for spec in ["0,0; 3,4", "1,1; 1,1", "0,0; 3,4; 3,0; 0,0"] {
        let report = match format_report(spec) { Ok(v) => v, Err(e) => return Err(e.into()) };
        println!("[{}]\n{}\n", spec, report);
    }
    let a = match parse_point("0,0") { Ok(v) => v, Err(e) => return Err(e.into()) };
    let b = match parse_point("3,4") { Ok(v) => v, Err(e) => return Err(e.into()) };
    println!("distance_2d({:?}, {:?}) = {}", a, b, distance_2d(a, b));
    Ok(())
}

