use std::collections::HashMap;

fn update_inventory(
    current: Vec<(&str, u32)>,
    changes: Vec<(&str, i32)>,
) -> Result<Vec<(String, u32)>, String> {
    let mut inventory: HashMap<String, u32> = HashMap::new();

