fn parse_int(s: &str) -> Option<i32> {
    let mut chars = s.chars();

    let first_char = chars.next()?;

    let (sign, mut start_index) = if first_char == '-' {
        (-1, 1)
    } else if first_char == '+' {
        (1, 1)
    } else {
        (1, 0)
    };

    let s_trimmed = if start_index == 1 {
        s.get(1..)?
    } else {
        s
    };

    if s_trimmed.is_empty() {
        return None;
    }

    let mut result: i32 = 0;

    for c in s_trimmed.chars() {
        let digit = c.to_digit(10)?;

        let digit_i32 = digit as i32;

        let next_result_positive = result.checked_mul(10)?;

        let next_result = next_result_positive.checked_add(digit_i32)?;

        result = next_result;
    }

    result.checked_mul(sign)
}

fn main() {
    println!("{:?}", parse_int("123"));
    println!("{:?}", parse_int("-456"));
    println!("{:?}", parse_int("+789"));
