fn is_valid_email(email: &str) -> bool {
    split_address(email).is_some()
}

/// Splits an address at its '@' provided a '.' follows somewhere in the domain,
/// which is exactly the "very basic" rule: '@' present, '.' present, '@' first.
fn split_address(email: &str) -> Option<(&str, &str)> {
    let (local, domain) = email.split_once('@')?;
    if domain.contains('.') {
        Some((local, domain))
    } else {
        None
    }
}

fn domain_of(email: &str) -> Option<&str> {
    let (_, domain) = split_address(email)?;
    Some(domain)
}

/// The label after the final '.', when there is one; `None` for "a@b.".
fn tld_of(email: &str) -> Option<&str> {
    let domain = domain_of(email)?;
    let last_dot = domain.rfind('.')?;
    let tld = &domain[last_dot + 1..];
    if tld.is_empty() {
        None
    } else {
        Some(tld)
    }
}

struct Contact {
    name: String,
    email: String,
    local: String,
    domain: String,
}

fn parse_contact(line: &str) -> Result<Contact, String> {
    let (name, addr) = line
        .split_once(',')
        .ok_or_else(|| format!("no ',' separating name and address in {:?}", line))?;
    let name = name.trim();
    let addr = addr.trim();
    let (local, domain) =
        split_address(addr).ok_or_else(|| format!("not a valid email: {:?}", addr))?;
    if name.is_empty() {
        return Err(format!("empty name in {:?}", line));
    }
    Ok(Contact {
        name: name.to_string(),
        email: addr.to_string(),
        local: local.to_string(),
        domain: domain.to_string(),
    })
}

fn format_contact(line: &str) -> Result<String, String> {
    let contact = parse_contact(line)?;
    let tld = tld_of(&contact.email)
        .ok_or_else(|| format!("no top level domain in {:?}", contact.domain))?;
    Ok(format!(
        "{} <{}>  local={}  domain={}  tld={}",
        contact.name, contact.email, contact.local, contact.domain, tld
    ))
}

fn report(lines: &[&str]) -> Result<String, String> {
    let mut out = String::new();
    for line in lines {
        let formatted = format_contact(line)?;
        out.push_str(&formatted);
        out.push('\n');
    }
    Ok(out)
}

fn main() -> Result<(), String> {
    for probe in ["test@example.com", "invalid-email", "a@b.", "user@sub.site.org"] {
        println!("{:>20} -> {}", probe, is_valid_email(probe));
    }

    let roster = [
        "Ada Lovelace, ada@analytical.engine.uk",
        "Grace Hopper, grace@navy.mil",
    ];
    let text = report(&roster)?;
    print!("{}", text);

    match report(&["Nobody, invalid-email"]) {
        Ok(text) => print!("{}", text),
        Err(err) => println!("rejected: {}", err),
    }
    Ok(())
}

