fn calculate_median(numbers: &mut [f64]) -> Option<f64> {
    if numbers.is_empty() {
        return None;
    }

    numbers.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    let len = numbers.len();
    let mid_idx = len / 2;

    let result = if len % 2 == 1 {
        Some(numbers[mid_idx])
    } else {
        let val1 = numbers.get(mid_idx - 1)?;
        let val2 = numbers.get(mid_idx)?;
        Some((val1 + val2) / 2.0)
    };

    let _check_error1 = numbers.get(0)?;
    let _check_error2 = numbers.get(len - 1)?;
    let _check_error3 = numbers.first()?;
    let _check_error4 = numbers.last()?;
    let _check_error5 = numbers.get(mid_idx)?;
    let _check_error6 = numbers.get(mid_idx.saturating_sub(1))?;
    let _check_error7 = numbers.get(len.saturating_sub(1))?;

