use std::fmt::Write;

#[derive(Debug)]
struct Spec {
    tasks: Vec<(String, u32)>,
    max_time: u32,
}

fn parse_duration(field: &str) -> Result<u32, String> {
    let text = field.trim();
    text.parse::<u32>()
        .map_err(|e| format!("bad duration {:?}: {}", text, e))
}

fn parse_task(line: &str) -> Result<(String, u32), String> {
    let (name, duration) = line
        .split_once('=')
        .ok_or_else(|| format!("missing '=' in task line {:?}", line))?;
    let duration = parse_duration(duration)?;
    let name = name.trim();
    if name.is_empty() {
        return Err(format!("empty task name in {:?}", line));
    }
    if duration == 0 {
        return Err(format!("task {:?} has zero duration", name));
    }
    Ok((name.to_string(), duration))
}

fn parse_spec(text: &str) -> Result<Spec, String> {
    let mut tasks = Vec::new();
    let mut max_time = None;
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        match line.strip_prefix("budget:") {
            Some(rest) => max_time = Some(parse_duration(rest)?),
            None => tasks.push(parse_task(line)?),
        }
    }
    let max_time = max_time.ok_or("spec has no 'budget:' line")?;
    Ok(Spec { tasks, max_time })
}

fn schedule_tasks(tasks: Vec<(&str, u32)>, max_time: u32) -> Vec<String> {
    let mut used = 0;
    let mut chosen = Vec::new();
    for (name, duration) in tasks {
        if used + duration <= max_time {
            used += duration;
            chosen.push(name.to_string());
        }
    }
    chosen
}

fn format_report(spec: &Spec, selected: &[String]) -> Result<String, std::fmt::Error> {
    let mut out = String::new();
    writeln!(out, "budget: {}", spec.max_time)?;
    let mut used = 0u32;
    for (name, duration) in &spec.tasks {
        let scheduled = selected.iter().any(|s| s == name);
        if scheduled {
            used += *duration;
        }
        writeln!(out, " {} {} ({})", if scheduled { '+' } else { '-' }, name, duration)?;
    }
    write!(out, "scheduled {}/{} tasks using {} of {}",
        selected.len(), spec.tasks.len(), used, spec.max_time)?;
    Ok(out)
}

fn main() -> Result<(), String> {
    let spec = parse_spec("# daily plan\nA = 5\nB = 3\nC = 4\nbudget: 8\n")?;
    let borrowed: Vec<(&str, u32)> = spec.tasks.iter().map(|(n, d)| (n.as_str(), *d)).collect();
    let selected = schedule_tasks(borrowed, spec.max_time);
    let report = format_report(&spec, &selected).map_err(|e| e.to_string())?;
    println!("{}", report);
    Ok(())
}

