fn find_longest_word(words: &[&str]) -> Option<String> {
    let mut longest_word: Option<String> = None;
    let mut max_len = 0;

    for word_str in words {
        let current_len = word_str.len();
        if current_len > max_len {
            max_len = current_len;
            longest_word = Some(word_str.to_string());
        }
    }
    longest_word
}

