use std::io::Read;

#[derive(Debug)]
enum RomanError {
    Empty,
    BadDigit(char),
    OutOfRange(i64),
    Input(std::io::Error),
}

fn main() -> Result<(), RomanError> {
    let numerals = collect_inputs()?;
    print!("{}", report(&numerals)?);
    let sum: u32 = numerals.iter().map(|r| roman_to_int(r)).sum();
    println!("{:>8} = {:>3}", "total", sum);
    Ok(())
}

/// Numerals come from the command line, or from stdin when no argument is given.
fn collect_inputs() -> Result<Vec<String>, RomanError> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if !args.is_empty() {
        return Ok(args);
    }
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).map_err(RomanError::Input)?;
    Ok(buf.split_whitespace().map(str::to_owned).collect())
}

fn report(numerals: &[String]) -> Result<String, RomanError> {
    let mut out = String::new();
    for numeral in numerals {
        let n = parse_roman(numeral)?;
        out.push_str(&format!("{:>8} = {:>3}\n", numeral.to_ascii_uppercase(), n));
    }
    Ok(out)
}

fn parse_roman(roman: &str) -> Result<u32, RomanError> {
    let total = sum_digits(roman)?;
    if total <= 0 || total > 100 {
        return Err(RomanError::OutOfRange(total));
    }
    Ok(total as u32)
}

/// Adds the digit values, subtracting any digit that precedes a larger one.
fn sum_digits(roman: &str) -> Result<i64, RomanError> {
    if roman.is_empty() {
        return Err(RomanError::Empty);
    }
    let values: Vec<i64> = roman.chars().map(|c| value_of(c.to_ascii_uppercase())).collect::<Result<_, _>>()?;
    let mut total = 0;
    for (i, v) in values.iter().enumerate() {
        if values.get(i + 1).map_or(false, |next| next > v) {
            total -= v;
        } else {
            total += v;
        }
    }
    Ok(total)
}

fn value_of(c: char) -> Result<i64, RomanError> {
    match c {
        'I' => Ok(1), 'V' => Ok(5), 'X' => Ok(10), 'L' => Ok(50), 'C' => Ok(100),
        other => Err(RomanError::BadDigit(other)),
    }
}

fn roman_to_int(roman: &str) -> u32 {
    match parse_roman(roman) {
        Ok(n) => n,
        Err(e) => panic!("roman_to_int({:?}): {:?}", roman, e),
    }
}

