use std::collections::HashMap;
use std::num::ParseIntError;

#[derive(Debug, Clone, Copy, PartialEq)]
enum Light {
    Red,
    Green,
    Yellow,
}

#[derive(Debug)]
enum LightError {
    UnknownState(String),
    MalformedLine(String),
    BadDuration(String, ParseIntError),
    MissingEntry(&'static str),
}

impl Light {
    fn parse(name: &str) -> Result<Light, LightError> {
        match name {
            "red" => Ok(Light::Red),
            "green" => Ok(Light::Green),
            "yellow" => Ok(Light::Yellow),
            other => Err(LightError::UnknownState(other.to_string())),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Light::Red => "red",
            Light::Green => "green",
            Light::Yellow => "yellow",
        }
    }

    fn next(self) -> Light {
        match self {
            Light::Red => Light::Green,
            Light::Green => Light::Yellow,
            Light::Yellow => Light::Red,
        }
    }
}

fn try_next_light(current: &str) -> Result<&'static str, LightError> {
    Ok(Light::parse(current)?.next().as_str())
}

fn get_next_light(current: &str) -> &'static str {
    try_next_light(current).expect("current must be red, yellow or green")
}

struct Schedule {
    durations: HashMap<&'static str, u32>,
}

impl Schedule {
    fn parse(text: &str) -> Result<Schedule, LightError> {
        let mut durations = HashMap::new();
        for line in text.lines().filter(|l| !l.trim().is_empty()) {
            let (name, value) = line
                .split_once('=')
                .ok_or_else(|| LightError::MalformedLine(line.to_string()))?;
            let light = Light::parse(name.trim())?;
            let secs = value
                .trim()
                .parse::<u32>()
                .map_err(|e| LightError::BadDuration(value.trim().to_string(), e))?;
            durations.insert(light.as_str(), secs);
        }
        for required in ["red", "green", "yellow"] {
            durations
                .get(required)
                .ok_or(LightError::MissingEntry(required))?;
        }
        Ok(Schedule { durations })
    }

    fn duration(&self, light: Light) -> u32 {
        self.durations[light.as_str()]
    }
}

fn cycle_from(start: &str, steps: usize, sched: &Schedule) -> Result<Vec<(&'static str, u32)>, LightError> {
    let mut light = Light::parse(start)?;
    let mut phases = Vec::with_capacity(steps);
    for _ in 0..steps {
        phases.push((light.as_str(), sched.duration(light)));
        light = light.next();
    }
    Ok(phases)
}

fn report(start: &str, steps: usize, config: &str) -> Result<String, LightError> {
    let sched = Schedule::parse(config)?;
    let mut out = String::new();
    let mut clock = 0;
    for (name, secs) in cycle_from(start, steps, &sched)? {
        out.push_str(&format!("t={:>3}s  {:<6} for {}s\n", clock, name, secs));
        clock += secs;
    }
    Ok(out)
}

fn main() -> Result<(), LightError> {
    println!("red    -> {}", get_next_light("red"));
    println!("yellow -> {}", get_next_light("yellow"));
    println!("green  -> {}", try_next_light("green")?);

    let config = "red = 30\ngreen = 25\nyellow = 5\n";
    print!("{}", report("red", 7, config)?);
    Ok(())
}

