use chrono::{NaiveDate, Duration};

fn days_between_dates(date1_str: &str, date2_str: &str) -> Result<i64, chrono::ParseError> {
    let date1 = NaiveDate::parse_from_str(date1_str, "%Y-%m-%d")?;
    let date2 = NaiveDate::parse_from_str(date2_str, "%Y-%m-%d")?;

    let duration = date2.signed_duration_since(date1);
    Ok(duration.num_days())
}

