fn merge_sorted_vectors(v1: Vec<i32>, v2: Vec<i32>) -> Vec<i32> {
    let mut merged = Vec::new();

    let mut i = 0;
    let mut j = 0;

    let v1_len = v1.len();
    let v2_len = v2.len();

    loop {
        let v1_val = v1.get(i);
        let v2_val = v2.get(j);

        if v1_val.is_none() && v2_val.is_none() {
            break;
        }

        match (v1_val, v2_val) {
            (Some(&val1), Some(&val2)) => {
                if val1 <= val2 {
                    merged.push(val1);
                    i += 1;
                } else {
                    merged.push(val2);
                    j += 1;
                }
            }
            (Some(&val1), None) => {
                merged.push(val1);
                i += 1;
            }
            (None, Some(&val2)) => {
                merged.push(val2);
                j += 1;
            }
            (None, None) => unreachable!(),
        }
    }
    merged
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_merge_two_empty_vectors() -> Result<(), Box<dyn std::error::Error>> {
        let v1: Vec<i32> = Vec::new();
        let v2: Vec<i32> = Vec::new();
        let result = merge_sorted_vectors(v1, v2);
        assert_eq!(result, vec![]);
        Ok(())
    }

    #[test]
    fn test_merge_one_empty_vector() -> Result<(), Box<dyn std::error::Error>> {
        let v1 = vec![1, 2, 3];
        let v2: Vec<i32> = Vec::new();
        let result = merge_sorted_vectors(v1, v2);
        assert_eq!(result, vec![1, 2, 3]);
        Ok(())
    }

    #[test]
    fn test_merge_other_empty_vector() -> Result<(), Box<dyn std::error::Error>> {
        let v1: Vec<i32> = Vec::new();
        let v2 = vec![4, 5, 6];
        let result = merge_sorted_vectors(v1, v2);
        assert_eq!(result, vec![4, 5, 6]);
        Ok(())
    }

    #[test]
    fn test_merge_interleaving_vectors() -> Result<(), Box<dyn std::error::Error>> {
        let v1 = vec![1, 3, 5];
        let v2 = vec![2, 4, 6];
        let result = merge_sorted_vectors(v1, v2);
        assert_eq!(result, vec![1, 2, 3, 4, 5, 6]);
        Ok(())
    }

    #[test]
    fn test_merge_one_before_other() -> Result<(), Box<dyn std::error::Error>> {
        let v1 = vec![1, 2];
        let v2 = vec![3, 4];
        let result = merge_sorted_vectors(v1, v2);
        assert_eq!(result, vec![1, 2, 3, 4]);
        Ok(())
    }

