use std::fmt;

#[derive(Debug)]
enum GridError {
    BadChar(char),
    BadRowLen(usize),
    BadRowCount(usize),
    Duplicate { unit: String, digit: u8 },
}

impl fmt::Display for GridError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            GridError::BadChar(c) => write!(f, "invalid character '{}'", c),
            GridError::BadRowLen(n) => write!(f, "row has {} cells, expected 9", n),
            GridError::BadRowCount(n) => write!(f, "grid has {} rows, expected 9", n),
            GridError::Duplicate { unit, digit } => {
                write!(f, "digit {} appears twice in {}", digit, unit)
            }
        }
    }
}

fn parse_digit(c: char) -> Result<u8, GridError> {
    match c {
        '.' | '0' => Ok(0),
        '1'..='9' => Ok(c as u8 - b'0'),
        other => Err(GridError::BadChar(other)),
    }
}

fn parse_row(line: &str) -> Result<[u8; 9], GridError> {
    let chars: Vec<char> = line.trim().chars().collect();
    if chars.len() != 9 {
        return Err(GridError::BadRowLen(chars.len()));
    }
    let mut row = [0u8; 9];
    for (i, c) in chars.iter().enumerate() {
        row[i] = parse_digit(*c)?;
    }
    Ok(row)
}

fn parse_grid(text: &str) -> Result<[[u8; 9]; 9], GridError> {
    let lines: Vec<&str> = text.lines().filter(|l| !l.trim().is_empty()).collect();
    if lines.len() != 9 {
        return Err(GridError::BadRowCount(lines.len()));
    }
    let mut grid = [[0u8; 9]; 9];
    for (i, line) in lines.iter().enumerate() {
        grid[i] = parse_row(line)?;
    }
    Ok(grid)
}

fn unit_ok(unit: &[u8; 9], name: &str) -> Result<(), GridError> {
    let mut seen = 0u16;
    for &d in unit.iter().filter(|&&d| d != 0) {
        let bit = 1u16 << d;
        if seen & bit != 0 {
            return Err(GridError::Duplicate { unit: name.to_string(), digit: d });
        }
        seen |= bit;
    }
    Ok(())
}

fn is_valid_sudoku_row(row: &[u8; 9]) -> bool {
    unit_ok(row, "row").is_ok()
}

fn column(grid: &[[u8; 9]; 9], c: usize) -> [u8; 9] {
    let mut col = [0u8; 9];
    for r in 0..9 {
        col[r] = grid[r][c];
    }
    col
}

fn block(grid: &[[u8; 9]; 9], b: usize) -> [u8; 9] {
    let mut cells = [0u8; 9];
    for i in 0..9 {
        cells[i] = grid[(b / 3) * 3 + i / 3][(b % 3) * 3 + i % 3];
    }
    cells
}

fn report(text: &str) -> Result<String, GridError> {
    let grid = parse_grid(text)?;
    for i in 0..9 {
        unit_ok(&grid[i], &format!("row {}", i + 1))?;
        unit_ok(&column(&grid, i), &format!("column {}", i + 1))?;
        unit_ok(&block(&grid, i), &format!("block {}", i + 1))?;
    }
    let filled = grid.iter().flatten().filter(|&&d| d != 0).count();
    Ok(format!("consistent grid, {} cells filled", filled))
}

fn main() -> Result<(), GridError> {
    let good = parse_row("530070000")?;
    println!("530070000 -> {}", is_valid_sudoku_row(&good));
    let bad = parse_row("530050000")?;
    println!("530050000 -> {}", is_valid_sudoku_row(&bad));

    let puzzle = "530070000\n600195000\n098000060\n800060003\n400803001\n\
                  700020006\n060000280\n000419005\n000080079";
    println!("{}", report(puzzle)?);

    let broken = puzzle.replace("098000060", "598000060");
    match report(&broken) {
        Ok(msg) => println!("{}", msg),
        Err(e) => println!("rejected: {}", e),
    }
    Ok(())
}

