use std::fmt;

#[derive(Debug)]
enum ConvError {
    UnknownUnit(String),
    BadNumber(String),
    BadFormat(String),
}

impl fmt::Display for ConvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConvError::UnknownUnit(u) => write!(f, "unknown unit: {u}"),
            ConvError::BadNumber(n) => write!(f, "not a number: {n}"),
            ConvError::BadFormat(l) => write!(f, "malformed request: {l}"),
        }
    }
}

/// Number of metres in one unit of `unit`.
fn unit_factor(unit: &str) -> Result<f64, ConvError> {
    match unit {
        "m" => Ok(1.0),
        "cm" => Ok(0.01),
        "km" => Ok(1000.0),
        other => Err(ConvError::UnknownUnit(other.to_string())),
    }
}

fn try_convert(value: f64, from_unit: &str, to_unit: &str) -> Result<f64, ConvError> {
    let from = unit_factor(from_unit)?;
    let to = unit_factor(to_unit)?;
    Ok(value * from / to)
}

fn convert_length(value: f64, from_unit: &str, to_unit: &str) -> f64 {
    try_convert(value, from_unit, to_unit).expect("units must be one of m, cm, km")
}

/// Parses a request of the form "100 cm -> m" and checks that both units exist,
/// so the resulting triple is safe to hand to `convert_length`.
