use std::collections::HashMap;
use std::fmt;

#[derive(Debug)]
enum LogError {
    MissingSeparator(String),
    BadTimestamp(String),
    NoEvents,
}

impl fmt::Display for LogError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            LogError::MissingSeparator(line) => write!(f, "missing ',' in log line: {line:?}"),
            LogError::BadTimestamp(ts) => write!(f, "malformed timestamp: {ts:?}"),
            LogError::NoEvents => write!(f, "log contains no events"),
        }
    }
}

fn parse_timestamp(stamp: &str) -> Result<u64, LogError> {
    let digits = stamp
        .strip_prefix('t')
        .ok_or_else(|| LogError::BadTimestamp(stamp.to_string()))?;
    let value = digits
        .parse::<u64>()
        .map_err(|_| LogError::BadTimestamp(stamp.to_string()))?;
    Ok(value)
}

fn parse_line(line: &str) -> Result<(&str, &str), LogError> {
    let (stamp, event) = line
        .split_once(',')
        .ok_or_else(|| LogError::MissingSeparator(line.to_string()))?;
    let stamp = stamp.trim();
    parse_timestamp(stamp)?;
    Ok((stamp, event.trim()))
}

fn parse_log(text: &str) -> Result<Vec<(&str, &str)>, LogError> {
    let mut logs = Vec::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        logs.push(parse_line(line)?);
    }
    Ok(logs)
}

fn process_event_log(logs: Vec<(&str, &str)>) -> HashMap<String, usize> {
    let mut counts = HashMap::new();
    for (_, event) in logs {
        *counts.entry(event.to_string()).or_insert(0) += 1;
    }
    counts
}

fn most_frequent(counts: &HashMap<String, usize>) -> Option<(&str, usize)> {
    let (event, count) = counts
        .iter()
        .max_by(|a, b| a.1.cmp(b.1).then_with(|| b.0.cmp(a.0)))?;
    Some((event.as_str(), *count))
}

fn time_span(logs: &[(&str, &str)]) -> Result<u64, LogError> {
    let mut earliest = u64::MAX;
    let mut latest = 0;
    for (stamp, _) in logs {
        let moment = parse_timestamp(stamp)?;
        earliest = earliest.min(moment);
        latest = latest.max(moment);
    }
    Ok(latest.saturating_sub(earliest))
}

fn format_report(text: &str) -> Result<String, LogError> {
    let logs = parse_log(text)?;
    let span = time_span(&logs)?;
    let counts = process_event_log(logs);
    let (top, top_count) = most_frequent(&counts).ok_or(LogError::NoEvents)?;
    let mut lines: Vec<String> = counts
        .iter()
        .map(|(event, count)| format!("  {event}: {count}"))
        .collect();
    lines.sort();
    lines.insert(0, format!("events over {span} ticks, busiest: {top} ({top_count})"));
    Ok(lines.join("\n"))
}

fn main() -> Result<(), LogError> {
    const RAW_LOG: &str = "t1,login\nt2,logout\nt3,login\nt7,upload\n";
    let report = format_report(RAW_LOG)?;
    println!("{report}");
    Ok(())
}

