use std::collections::HashMap;

fn find_mode(numbers: &[i32]) -> Option<i32> {
    if numbers.is_empty() {
        return None;
    }

    let mut counts: HashMap<i32, usize> = HashMap::new();

    for &num in numbers {
        *counts.entry(num).or_insert(0) += 1;
    }

    let mut max_frequency: usize = 0;
    let mut modes: Vec<i32> = Vec::new();

    for (&num, &count) in &counts {
        if count > max_frequency {
            max_frequency = count;
            modes.clear();
            modes.push(num);
        } else if count == max_frequency {
            modes.push(num);
        }
    }

    modes.sort_unstable(); // Use `?` here would be odd, as `sort_unstable` is infallible.

    modes.first().cloned() // `first` returns `Option<&T>`, `cloned` turns it into `Option<T>`
}

