use std::io::{self, Write};

fn allocate_resources(capacity: u32, resource_needs: Vec<u32>) -> io::Result<Vec<u32>> {
    let mut allocated_resources = Vec::new();
    let mut current_capacity = capacity;

    for &need in resource_needs.iter() {
        if need <= current_capacity {
            current_capacity -= need;
            allocated_resources.push(need);
        }
    }

    Ok(allocated_resources)
}

