use std::env;

#[derive(Debug)]
struct Report {
    shortest: String,
    longest: String,
    count: usize,
    mean_len: f64,
}

fn parse_record(line: &str) -> Result<(String, String), String> {
    let (label, sentence) = line
        .split_once(':')
        .ok_or_else(|| format!("missing ':' separator in {line:?}"))?;
    let label = label.trim();
    if label.is_empty() {
        return Err(format!("empty label in {line:?}"));
    }
    Ok((label.to_string(), sentence.to_string()))
}

fn clean_word(token: &str) -> Option<String> {
    let trimmed = token.trim_matches(|c: char| !c.is_alphanumeric());
    if trimmed.is_empty() {
        return None;
    }
    Some(trimmed.to_lowercase())
}

fn words(sentence: &str) -> Vec<String> {
    sentence.split_whitespace().filter_map(clean_word).collect()
}

fn find_shortest_word(sentence: &str) -> Option<String> {
    words(sentence).into_iter().min_by_key(|w| w.chars().count())
}

fn find_longest_word(sentence: &str) -> Option<String> {
    let mut best: Option<String> = None;
    for word in words(sentence) {
        if best.as_ref().map_or(true, |b: &String| word.chars().count() > b.chars().count()) {
            best = Some(word);
        }
    }
    best
}

fn build_report(sentence: &str) -> Option<Report> {
    let shortest = find_shortest_word(sentence)?;
    let longest = find_longest_word(sentence)?;
    let words = words(sentence);
    let total: usize = words.iter().map(|w| w.chars().count()).sum();
    Some(Report {
        shortest,
        longest,
        count: words.len(),
        mean_len: total as f64 / words.len() as f64,
    })
}

fn format_report(label: &str, sentence: &str) -> Option<String> {
    let report = build_report(sentence)?;
    Some(format!(
        "{label}: shortest={:?} longest={:?} words={} mean={:.2}",
        report.shortest, report.longest, report.count, report.mean_len
    ))
}

fn describe_record(line: &str) -> Result<String, String> {
    let (label, sentence) = parse_record(line)?;
    let text = format_report(&label, &sentence)
        .ok_or_else(|| format!("no words found for label {label:?}"))?;
    Ok(text)
}

fn process(lines: &[String]) -> Result<Vec<String>, String> {
    let mut out = Vec::with_capacity(lines.len());
    for line in lines {
        out.push(describe_record(line)?);
    }
    Ok(out)
}

fn main() -> Result<(), String> {
    let mut lines: Vec<String> = env::args().skip(1).collect();
    if lines.is_empty() {
        lines = vec![
            "greeting: Hello world, how are you?".to_string(),
            "quote: The quick brown fox jumps over a lazy dog!".to_string(),
        ];
    }
    for report in process(&lines)? {
        println!("{report}");
    }
    Ok(())
}

