use std::fmt;

#[derive(Debug, PartialEq)]
enum BinError {
    Empty,
    InvalidDigit(char),
    Overflow,
}

impl fmt::Display for BinError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            BinError::Empty => write!(f, "empty binary string"),
            BinError::InvalidDigit(c) => write!(f, "invalid binary digit '{}'", c),
            BinError::Overflow => write!(f, "value does not fit in a u32"),
        }
    }
}

fn parse_binary(binary_str: &str) -> Result<u32, BinError> {
    if binary_str.is_empty() {
        return Err(BinError::Empty);
    }
    let mut value: u32 = 0;
    for ch in binary_str.chars() {
        let digit = match ch {
            '0' => 0,
            '1' => 1,
            other => return Err(BinError::InvalidDigit(other)),
        };
        value = value.checked_mul(2).ok_or(BinError::Overflow)?;
        value = value.checked_add(digit).ok_or(BinError::Overflow)?;
    }
    Ok(value)
}

fn binary_to_decimal(binary_str: &str) -> u32 {
    parse_binary(binary_str).expect("input must contain only '0's and '1's")
}

fn decimal_to_binary(mut value: u32) -> String {
    if value == 0 {
        return String::from("0");
    }
    let mut digits = Vec::new();
    while value > 0 {
        digits.push(if value & 1 == 1 { '1' } else { '0' });
        value >>= 1;
    }
    digits.iter().rev().collect()
}

fn describe(binary_str: &str) -> Result<String, BinError> {
    let value = parse_binary(binary_str)?;
    let canonical = decimal_to_binary(value);
    Ok(format!(
        "{:>10} = {:<6} (canonical {})",
        binary_str, value, canonical
    ))
}

fn sum_binaries(entries: &[&str]) -> Result<u32, BinError> {
    let mut total: u32 = 0;
    for entry in entries {
        let value = parse_binary(entry)?;
        total = total.checked_add(value).ok_or(BinError::Overflow)?;
    }
    Ok(total)
}

