#[derive(Debug)]
enum EntryError {
    MissingIndex(String),
    BadIndex(ParseIntError),
    EmptySentence(usize),
    Format(fmt::Error),
}

impl fmt::Display for EntryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            EntryError::MissingIndex(line) => write!(f, "line {line:?} has no ':' separator"),
            EntryError::BadIndex(e) => write!(f, "bad entry index: {e}"),
            EntryError::EmptySentence(i) => write!(f, "entry {i} carries no words"),
            EntryError::Format(e) => write!(f, "formatting failed: {e}"),
        }
    }
}

impl From<ParseIntError> for EntryError {
    fn from(e: ParseIntError) -> Self {
        EntryError::BadIndex(e)
    }
}

impl From<fmt::Error> for EntryError {
    fn from(e: fmt::Error) -> Self {
        EntryError::Format(e)
    }
}

fn reverse_words_in_sentence(sentence: &str) -> String {
    let mut words: Vec<&str> = sentence.split_whitespace().collect();
    words.reverse();
    words.join(" ")
}

fn parse_entry(line: &str) -> Result<(usize, &str), EntryError> {
    let (index, rest) = line
        .split_once(':')
        .ok_or_else(|| EntryError::MissingIndex(line.to_string()))?;
    let index: usize = index.trim().parse()?;
    let sentence = rest.trim();
    if sentence.is_empty() {
        return Err(EntryError::EmptySentence(index));
    }
    Ok((index, sentence))
}

