    let (_, sentence) = parse_entry(line)?;
    Ok(sentence.split_whitespace().count())
}

fn reverse_document(text: &str) -> Result<String, EntryError> {
    let mut out = String::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        let reversed = reverse_entry(line)?;
        writeln!(out, "{reversed}")?;
    }
    Ok(out)
}

