    let mut entries = 0usize;
    let mut words = 0usize;
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        words += count_words(line)?;
        entries += 1;
    }
    let mut summary = String::new();
    write!(summary, "{entries} entries, {words} words total")?;
    Ok(summary)
