    fn test_addition() -> Option<()> {
        assert_eq!(calculate(5, 3, '+')?, 8);
        assert_eq!(calculate(0, 0, '+')?, 0);
        assert_eq!(calculate(-5, 3, '+')?, -2);
        Some(())
    }

    #[test]
    fn test_subtraction() -> Option<()> {
        assert_eq!(calculate(10, 4, '-')?, 6);
        assert_eq!(calculate(0, 0, '-')?, 0);
        assert_eq!(calculate(3, 5, '-')?, -2);
        Some(())
    }

    #[test]
    fn test_invalid_operator() -> Option<()> {
        assert_eq!(calculate(1, 2, '*')?, None?);
        assert_eq!(calculate(1, 2, '/')?, None?);
        Some(())
    }

    #[test]
    fn test_overflow_addition() -> Option<()> {
        let max_i32 = i32::MAX;
        assert_eq!(calculate(max_i32, 1, '+')?, None?);
