fn days_in_month(year: u16, month: u8) -> Option<u8> {
    let days = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            let is_leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
            if is_leap {
                29
            } else {
                28
            }
        }
        _ => return None,
    };
    Some(days)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let days1 = days_in_month(2023, 2)
        .ok_or("Invalid month or year for days_in_month")?;

    println!("Days in Feb 2023: {}", days1);

    let days2 = days_in_month(2024, 2)
        .ok_or("Invalid month or year for days_in_month")?;

    println!("Days in Feb 2024: {}", days2);

    let days3 = days_in_month(2023, 1)
        .ok_or("Invalid month or year for days_in_month")?;

    println!("Days in Jan 2023: {}", days3);

    let days4 = days_in_month(2023, 4)
        .ok_or("Invalid month or year for days_in_month")?;

    println!("Days in Apr 2023: {}", days4);

    let days5 = days_in_month(2000, 2)
        .ok_or("Invalid month or year for days_in_month")?;

    println!("Days in Feb 2000: {}", days5);

    let days6 = days_in_month(1900, 2)
        .ok_or("Invalid month or year for days_in_month")?;

    println!("Days in Feb 1900: {}", days6);

