fn circle_circumference(radius: f64) -> f64 {
    let pi: f64 = std::f64::consts::PI;
    let diameter: f64 = 2.0 * radius;
    let circumference: f64 = pi * diameter;
    circumference
}

fn calculate_and_print_circumference(input_str: &str) -> Result<(), Box<dyn std::error::Error>> {
    let parsed_radius: f64 = input_str.trim().parse()?;

    let result: f64 = circle_circumference(parsed_radius);

    println!("The circumference for radius {} is {}", parsed_radius, result);
    Ok(())
}

