use std::collections::HashMap;
use std::fmt::{self, Display, Write};

const CREDENTIAL_TABLE: &str = "admin:password123\nguest:guest";

#[derive(Debug)]
enum AuthError {
    MalformedEntry(String),
    EmptyField(&'static str),
    MalformedRequest(String),
    Format(fmt::Error),
}

impl Display for AuthError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AuthError::MalformedEntry(line) => write!(f, "malformed credential entry: {:?}", line),
            AuthError::EmptyField(name) => write!(f, "empty {}", name),
            AuthError::MalformedRequest(req) => write!(f, "malformed login request: {:?}", req),
            AuthError::Format(err) => write!(f, "formatting failure: {}", err),
        }
    }
}

impl From<fmt::Error> for AuthError {
    fn from(err: fmt::Error) -> Self {
        AuthError::Format(err)
    }
}

fn non_empty<'a>(field: &'a str, name: &'static str) -> Result<&'a str, AuthError> {
    let trimmed = field.trim();
    if trimmed.is_empty() {
        return Err(AuthError::EmptyField(name));
    }
    Ok(trimmed)
}

fn parse_entry(line: &str) -> Result<(String, String), AuthError> {
    let (user, pass) = line
        .split_once(':')
        .ok_or_else(|| AuthError::MalformedEntry(line.to_string()))?;
    let user = non_empty(user, "username")?;
    let pass = non_empty(pass, "password")?;
    Ok((user.to_string(), pass.to_string()))
}

fn load_credentials(text: &str) -> Result<HashMap<String, String>, AuthError> {
    let mut table = HashMap::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        let (user, pass) = parse_entry(line)?;
        table.insert(user, pass);
    }
    Ok(table)
}

fn check_login(username: &str, password: &str) -> bool {
    match load_credentials(CREDENTIAL_TABLE) {
        Ok(table) => table.get(username).map_or(false, |stored| stored == password),
        Err(_) => false,
    }
}

fn authenticate(request: &str) -> Result<bool, AuthError> {
    let (user, pass) = request
        .split_once(' ')
        .ok_or_else(|| AuthError::MalformedRequest(request.to_string()))?;
    let user = non_empty(user, "username")?;
    let pass = non_empty(pass, "password")?;
    Ok(check_login(user, pass))
}

fn report(requests: &[&str]) -> Result<String, AuthError> {
    let mut out = String::new();
    for request in requests {
        let granted = authenticate(request)?;
        writeln!(out, "{:<22} => {}", request, if granted { "granted" } else { "denied" })?;
    }
    Ok(out)
}

fn main() -> Result<(), AuthError> {
    let requests = ["admin password123", "user wrongpass", "guest guest"];
    print!("{}", report(&requests)?);
    Ok(())
}

