use std::error::Error;
use std::fmt::{self, Write as FmtWrite};
use std::io::Read;

#[derive(Debug)]
struct ParseError(String);

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl Error for ParseError {}

impl From<fmt::Error> for ParseError {
    fn from(e: fmt::Error) -> Self {
        ParseError(format!("could not build report: {e}"))
    }
}

fn count_uppercase(s: &str) -> usize {
    s.chars().filter(|c| c.is_uppercase()).count()
}

struct Record {
    label: String,
    text: String,
}

fn split_record(line: &str) -> Result<(&str, &str), ParseError> {
    let sep = match line
        .find(':')
        .ok_or_else(|| ParseError(format!("missing ':' in record {line:?}")))
    {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok((&line[..sep], &line[sep + 1..]))
}

fn validate_label(label: &str) -> Result<String, ParseError> {
    let label = label.trim();
    if label.is_empty() {
        return Err(ParseError("record has an empty label".into()));
    }
    Ok(label.to_string())
}

fn parse_record(line: &str) -> Result<Record, ParseError> {
    let (label, text) = match split_record(line) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(Record {
        label: match validate_label(label) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        },
        text: text.trim().to_string(),
    })
}

fn parse_threshold(spec: &str) -> Result<usize, ParseError> {
    spec.trim()
        .parse::<usize>()
        .map_err(|e| ParseError(format!("bad threshold {spec:?}: {e}")))
}

fn report(input: &str) -> Result<String, ParseError> {
    let mut lines = input.lines();
    let head = match lines
        .next()
        .ok_or_else(|| ParseError("input must start with a threshold line".into()))
    {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let threshold = match parse_threshold(head) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let mut out = String::new();
    let mut total = 0usize;
    for line in lines.filter(|l| !l.trim().is_empty()) {
        let record = match parse_record(line) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        let uppers = count_uppercase(&record.text);
        total += uppers;
        if uppers >= threshold {
            match writeln!(out, "{:<12} {}", record.label, uppers) {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            }
        }
    }
    match writeln!(out, "{:<12} {}", "TOTAL", total) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }
    Ok(out)
}

fn run(input: &str) -> Result<(), ParseError> {
    print!("{}", match report(input) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });
    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut buf = String::new();
    match std::io::stdin().read_to_string(&mut buf) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    match run(&buf) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(())
}

