fn calculate_grade_average(grades: &[u8]) -> Option<f64> {
    if grades.is_empty() {
        return None;
    }

    let mut sum: u64 = 0;
    let mut count: u64 = 0;

    for &grade in grades {
        let current_sum: u64 = sum.checked_add(grade as u64)?;
        sum = current_sum;

        let current_count: u64 = count.checked_add(1)?;
        count = current_count;
    }

    if count == 0 {
        return None;
    }

    let sum_f64: f64 = sum as f64;
    let count_f64: f64 = count as f64;

    let average: f64 = sum_f64.checked_div(count_f64)?;

    Some(average)
}

