use std::error::Error;
use std::fmt::{self, Write as FmtWrite};
use std::io::Write as IoWrite;
use std::num::ParseIntError;

#[derive(Debug)]
enum SummaryError {
    Parse(ParseIntError),
    Empty,
    Format(fmt::Error),
}

impl fmt::Display for SummaryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SummaryError::Parse(e) => write!(f, "bad number: {}", e),
            SummaryError::Empty => write!(f, "no statistics for an empty list"),
            SummaryError::Format(e) => write!(f, "formatting failed: {}", e),
        }
    }
}

impl Error for SummaryError {}

impl From<ParseIntError> for SummaryError {
    fn from(e: ParseIntError) -> Self {
        SummaryError::Parse(e)
    }
}

impl From<fmt::Error> for SummaryError {
    fn from(e: fmt::Error) -> Self {
        SummaryError::Format(e)
    }
}

fn parse_numbers(spec: &str) -> Result<Vec<i32>, SummaryError> {
    let mut values = Vec::new();
    for field in spec.split(',').map(str::trim).filter(|f| !f.is_empty()) {
        values.push(field.parse::<i32>()?);
    }
    Ok(values)
}

fn sort_vector_in_place(numbers: &mut Vec<i32>) {
    for i in 1..numbers.len() {
        let key = numbers[i];
        let mut j = i;
        while j > 0 && numbers[j - 1] > key {
            numbers[j] = numbers[j - 1];
            j -= 1;
        }
        numbers[j] = key;
    }
}

fn median(sorted: &[i32]) -> Result<f64, SummaryError> {
    let mid = sorted.len() / 2;
    let high = *sorted.get(mid).ok_or(SummaryError::Empty)?;
    if sorted.len() % 2 == 1 {
        return Ok(high as f64);
    }
    let low = *sorted.get(mid - 1).ok_or(SummaryError::Empty)?;
    Ok((low as f64 + high as f64) / 2.0)
}

fn span(sorted: &[i32]) -> Result<i32, SummaryError> {
    let low = *sorted.first().ok_or(SummaryError::Empty)?;
    let high = *sorted.last().ok_or(SummaryError::Empty)?;
    Ok(high - low)
}

fn summarize(spec: &str) -> Result<String, SummaryError> {
    let mut numbers = parse_numbers(spec)?;
    sort_vector_in_place(&mut numbers);
    let middle = median(&numbers)?;
    let width = span(&numbers)?;
    let mut report = String::new();
    for value in &numbers {
        write!(report, "{} ", value)?;
    }
    write!(report, "| median={:.1} span={}", middle, width)?;
    Ok(report)
}

fn main() -> Result<(), Box<dyn Error>> {
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for spec in ["3, 1, 4, 1, 5", "", "10,-2,7,7", "42", "8,nine"] {
        match summarize(spec) {
            Ok(report) => writeln!(out, "{:>14} -> {}", spec, report)?,
            Err(err) => writeln!(out, "{:>14} -> error: {}", spec, err)?,
        }
    }
    out.flush()?;
    Ok(())
}

