use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum ConfigError {
    MissingSeparator(usize),
    MissingKey(String),
    UnknownMode(String),
    BadNumber(ParseIntError),
}

impl From<ParseIntError> for ConfigError {
    fn from(e: ParseIntError) -> Self {
        ConfigError::BadNumber(e)
    }
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::MissingSeparator(n) => write!(f, "line {n}: expected KEY=VALUE"),
            ConfigError::MissingKey(k) => write!(f, "missing required key '{k}'"),
            ConfigError::UnknownMode(m) => write!(f, "unknown mode '{m}'"),
            ConfigError::BadNumber(e) => write!(f, "invalid number: {e}"),
        }
    }
}

fn to_lowercase_string(s: &str) -> String {
    s.chars().flat_map(|c| c.to_lowercase()).collect()
}

fn parse_entry(line: &str, lineno: usize) -> Result<(String, String), ConfigError> {
    let (raw_key, raw_value) = match line.split_once('=').ok_or(ConfigError::MissingSeparator(lineno)) { Ok(v) => v, Err(e) => return Err(e.into()) };
    Ok((to_lowercase_string(raw_key.trim()), raw_value.trim().to_string()))
}

fn parse_config(text: &str) -> Result<Vec<(String, String)>, ConfigError> {
    text.lines().enumerate()
        .map(|(index, line)| (index + 1, line.trim()))
        .filter(|(_, line)| !line.is_empty() && !line.starts_with('#'))
        .map(|(lineno, line)| parse_entry(line, lineno))
        .collect()
}

fn lookup<'a>(entries: &'a [(String, String)], key: &str) -> Option<&'a str> {
    entries.iter().find(|(k, _)| k == key).map(|(_, v)| v.as_str())
}
fn require<'a>(entries: &'a [(String, String)], key: &str) -> Result<&'a str, ConfigError> {
    lookup(entries, key).ok_or_else(|| ConfigError::MissingKey(key.to_string()))
}

fn port_of(entries: &[(String, String)]) -> Result<u16, ConfigError> {
    let raw = match require(entries, "port") { Ok(v) => v, Err(e) => return Err(e.into()) };
    Ok(match raw.parse::<u16>() { Ok(v) => v, Err(e) => return Err(e.into()) })
}

fn mode_of(entries: &[(String, String)]) -> Result<String, ConfigError> {
    let mode = to_lowercase_string(match require(entries, "mode") { Ok(v) => v, Err(e) => return Err(e.into()) });
    if mode == "debug" || mode == "release" {
        return Ok(mode);
    }
    Err(ConfigError::UnknownMode(mode))
}

fn render_report(entries: &[(String, String)]) -> Result<String, ConfigError> {
    let host = to_lowercase_string(match require(entries, "host") { Ok(v) => v, Err(e) => return Err(e.into()) });
    let port = match port_of(entries) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let mode = match mode_of(entries) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let banner = to_lowercase_string(lookup(entries, "banner").unwrap_or("HELLO WORLD"));
    Ok(format!(
        "host = {host}\nport = {port}\nmode = {mode}\nbanner = {banner}"
    ))
}

fn main() -> Result<(), ConfigError> {
    let text = "# deployment settings\nHost = Example.COM\nPORT=8080\nMode = Release\nBanner = Rust\n";
    let entries = match parse_config(text) { Ok(v) => v, Err(e) => return Err(e.into()) };
    println!("{}", match render_report(&entries) { Ok(v) => v, Err(e) => return Err(e.into()) });
    Ok(())
}

