use std::fmt;

#[derive(Debug)]
enum AgeError {
    BadYear(String),
    MissingField(String),
    FutureBirth { birth_year: u16, current_year: u16 },
    NoRecords,
}

impl fmt::Display for AgeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AgeError::BadYear(text) => write!(f, "'{}' is not a valid year", text),
            AgeError::MissingField(line) => write!(f, "record '{}' needs name,year", line),
            AgeError::FutureBirth { birth_year, current_year } => {
                write!(f, "birth year {} is after current year {}", birth_year, current_year)
            }
            AgeError::NoRecords => write!(f, "no records to report"),
        }
    }
}

fn calculate_age(birth_year: u16, current_year: u16) -> u16 {
    current_year - birth_year
}

fn parse_year(text: &str) -> Result<u16, AgeError> {
    let trimmed = text.trim();
    let year = trimmed
        .parse::<u16>()
        .map_err(|_| AgeError::BadYear(trimmed.to_string()))?;
    if year < 1000 || year > 9999 {
        return Err(AgeError::BadYear(trimmed.to_string()));
    }
    Ok(year)
}

fn parse_record(line: &str) -> Result<(String, u16), AgeError> {
    let (name, year_text) = line
        .split_once(',')
        .ok_or_else(|| AgeError::MissingField(line.to_string()))?;
    let year = parse_year(year_text)?;
    Ok((name.trim().to_string(), year))
}

fn checked_age(birth_year: u16, current_year: u16) -> Result<u16, AgeError> {
    if birth_year > current_year {
        return Err(AgeError::FutureBirth { birth_year, current_year });
    }
    Ok(calculate_age(birth_year, current_year))
}

fn format_row(line: &str, current_year: u16) -> Result<String, AgeError> {
    let (name, birth_year) = parse_record(line)?;
    let age = checked_age(birth_year, current_year)?;
    Ok(format!("{:<8} born {} -> age {}", name, birth_year, age))
}

fn oldest_age(lines: &[&str], current_year: u16) -> Result<u16, AgeError> {
    let mut best: Option<u16> = None;
    for line in lines {
        let (_, birth_year) = parse_record(line)?;
        let age = checked_age(birth_year, current_year)?;
        best = Some(best.map_or(age, |b| b.max(age)));
    }
    best.ok_or(AgeError::NoRecords)
}

fn build_report(lines: &[&str], current_year_text: &str) -> Result<String, AgeError> {
    let current_year = parse_year(current_year_text)?;
    let mut out = String::new();
    for line in lines {
        out.push_str(&format_row(line, current_year)?);
        out.push('\n');
    }
    out.push_str(&format!("oldest age: {}\n", oldest_age(lines, current_year)?));
    Ok(out)
}

fn main() -> Result<(), AgeError> {
    let people = ["Alice, 1990", "Bob, 2020", "Cara, 1948"];
    print!("{}", build_report(&people, "2023")?);
    match build_report(&["Dan, 2031"], "2023") {
        Ok(report) => print!("{}", report),
        Err(err) => println!("rejected: {}", err),
    }
    Ok(())
}

