use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum InputError {
    Empty,
    BadDigits(ParseIntError),
    BadRange(String),
}

impl fmt::Display for InputError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            InputError::Empty => write!(f, "empty input token"),
            InputError::BadDigits(e) => write!(f, "not a valid u32: {}", e),
            InputError::BadRange(s) => write!(f, "malformed range: {}", s),
        }
    }
}

impl From<ParseIntError> for InputError {
    fn from(e: ParseIntError) -> Self {
        InputError::BadDigits(e)
    }
}

fn count_set_bits(n: u32) -> u32 {
    let mut value = n;
    let mut bits = 0;
    while value != 0 {
        value &= value - 1;
        bits += 1;
    }
    bits
}

fn parse_number(token: &str) -> Result<u32, InputError> {
    let t = token.trim();
    if t.is_empty() {
        return Err(InputError::Empty);
    }
    if let Some(hex) = t.strip_prefix("0x") {
        return Ok(u32::from_str_radix(hex, 16)?);
    }
    if let Some(bin) = t.strip_prefix("0b") {
        return Ok(u32::from_str_radix(bin, 2)?);
    }
    Ok(t.parse::<u32>()?)
}

fn describe(token: &str) -> Result<String, InputError> {
    let n = parse_number(token)?;
    Ok(format!("{:>10} = 0b{:032b} -> {} set bits", n, n, count_set_bits(n)))
}

fn parse_range(spec: &str) -> Result<(u32, u32), InputError> {
    let (lo, hi) = spec.split_once("..").ok_or_else(|| InputError::BadRange(spec.to_string()))?;
    let start = parse_number(lo)?;
    let end = parse_number(hi)?;
    if start > end {
        return Err(InputError::BadRange(spec.to_string()));
    }
    Ok((start, end))
}

fn range_set_bits(spec: &str) -> Result<u32, InputError> {
    let (start, end) = parse_range(spec)?;
    Ok((start..=end).map(count_set_bits).sum())
}

fn report(token: &str) -> Result<String, InputError> {
    if token.contains("..") {
        let total = range_set_bits(token)?;
        return Ok(format!("{:>10} -> {} set bits in total", token, total));
    }
    describe(token)
}

fn main() -> Result<(), InputError> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let tokens: Vec<String> = if args.is_empty() {
        vec!["9".into(), "7".into(), "0xff".into(), "0b101010".into(), "1..16".into()]
    } else {
        args
    };
    for token in &tokens {
        println!("{}", report(token)?);
    }
    Ok(())
}

