        value &= value - 1;
        bits += 1;
    }
    bits
}

fn parse_number(token: &str) -> Result<u32, InputError> {
    let t = token.trim();
    if t.is_empty() {
        return Err(InputError::Empty);
    }
    if let Some(hex) = t.strip_prefix("0x") {
        return Ok(match u32::from_str_radix(hex, 16) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        });
    }
    if let Some(bin) = t.strip_prefix("0b") {
        return Ok(match u32::from_str_radix(bin, 2) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        });
    }
    Ok(match t.parse::<u32>() {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    })
}

fn describe(token: &str) -> Result<String, InputError> {
    let n = match parse_number(token) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(format!("{:>10} = 0b{:032b} -> {} set bits", n, n, count_set_bits(n)))
}

fn parse_range(spec: &str) -> Result<(u32, u32), InputError> {
    let (lo, hi) = match spec.split_once("..").ok_or_else(|| InputError::BadRange(spec.to_string())) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let start = match parse_number(lo) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let end = match parse_number(hi) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    if start > end {
        return Err(InputError::BadRange(spec.to_string()));
    }
    Ok((start, end))
}

fn range_set_bits(spec: &str) -> Result<u32, InputError> {
    let (start, end) = match parse_range(spec) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok((start..=end).map(count_set_bits).sum())
}

fn report(token: &str) -> Result<String, InputError> {
    if token.contains("..") {
        let total = match range_set_bits(token) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        return Ok(format!("{:>10} -> {} set bits in total", token, total));
    }
    describe(token)
}

fn main() -> Result<(), InputError> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let tokens: Vec<String> = if args.is_empty() {
        vec!["9".into(), "7".into(), "0xff".into(), "0b101010".into(), "1..16".into()]
    } else {
        args
    };
    for token in &tokens {
        println!("{}", match report(token) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        });
    }
    Ok(())
}

