fn reverse_chars_in_words(sentence: &str) -> String {
    sentence
        .split_whitespace()
        .map(|word| word.chars().rev().collect::<String>())
        .collect::<Vec<String>>()
        .join(" ")
}

fn validate_sentence(sentence: &str) -> Result<&str, String> {
    let trimmed = sentence.trim();
    if trimmed.is_empty() {
        return Err("sentence contains no words".to_string());
    }
    if let Some(bad) = trimmed.chars().find(|c| c.is_control()) {
        return Err(format!("sentence contains control character {:?}", bad));
    }
    Ok(trimmed)
}

fn reverse_checked(sentence: &str) -> Result<String, String> {
    let cleaned = validate_sentence(sentence)?;
    Ok(reverse_chars_in_words(cleaned))
}

fn parse_directive(line: &str) -> Result<(usize, &str), String> {
    let (id_part, text) = line
        .split_once(':')
        .ok_or_else(|| format!("missing ':' separator in {:?}", line))?;
    let id = id_part
        .trim()
        .parse::<usize>()
        .map_err(|e| format!("bad id {:?}: {}", id_part.trim(), e))?;
    let sentence = validate_sentence(text)?;
    Ok((id, sentence))
}

fn format_directive(line: &str) -> Result<String, String> {
    let (id, sentence) = parse_directive(line)?;
    let reversed = reverse_checked(sentence)?;
    Ok(format!("{:>3}: {}", id, reversed))
}

fn build_report(lines: &[&str]) -> Result<String, String> {
    let mut report = String::new();
    for line in lines {
        let formatted = format_directive(line)?;
        report.push_str(&formatted);
        report.push('\n');
    }
    Ok(report)
}

fn process_document(text: &str) -> Result<String, String> {
    let lines: Vec<&str> = text
        .lines()
        .filter(|line| !line.trim().is_empty())
        .collect();
    if lines.is_empty() {
        return Err("document contains no directives".to_string());
    }
    build_report(&lines)
}

fn main() -> Result<(), String> {
    println!("{}", reverse_chars_in_words("hello world"));
    println!("{}", reverse_chars_in_words("Rust is fun"));

    let document = "1: hello world\n\n2: Rust is fun\n3:   the quick brown fox  \n";
    print!("{}", process_document(document)?);
    Ok(())
}

