use std::fmt::Write as _;

/// Removes the character at character index `n`, or returns `None` when the
/// index does not address a character of `s`.
fn remove_nth_char(s: &str, n: usize) -> Option<String> {
    let (start, ch) = s.char_indices().nth(n)?;
    let mut out = String::with_capacity(s.len() - ch.len_utf8());
    out.push_str(&s[..start]);
    out.push_str(&s[start + ch.len_utf8()..]);
    Some(out)
}

/// Removes several characters at once. Indices refer to the original string,
/// so they are applied from the highest to the lowest.
fn remove_indices(s: &str, indices: &[usize]) -> Option<String> {
    let mut sorted = indices.to_vec();
    sorted.sort_unstable_by(|a, b| b.cmp(a));
    let mut current = s.to_string();
    for n in sorted {
        current = remove_nth_char(&current, n)?;
    }
    Some(current)
}

/// Parses a line of the form `word index`.
fn parse_command(line: &str) -> Result<(String, usize), String> {
    let mut parts = line.split_whitespace();
    let word = parts.next().ok_or_else(|| format!("missing word in {line:?}"))?;
    let index = parts.next().ok_or_else(|| format!("missing index in {line:?}"))?;
    let n: usize = index.parse().map_err(|_| format!("bad index {index:?}"))?;
    Ok((word.to_string(), n))
}

/// Removes the requested character, reporting the reason for any failure.
fn cut(word: &str, n: usize) -> Result<String, String> {
    remove_nth_char(word, n).ok_or_else(|| format!("index {n} out of bounds for {word:?}"))
}

/// Executes one command line and describes its outcome.
fn describe_command(line: &str) -> Result<String, String> {
    let (word, n) = parse_command(line)?;
    let result = cut(&word, n)?;
    Ok(format!("{word} without char {n} -> {result}"))
}

/// Turns a batch of commands into a human readable report, stopping at the
/// first malformed or out-of-range command.
fn format_report(lines: &[&str]) -> Result<String, String> {
    let mut report = String::new();
    for line in lines {
        let entry = describe_command(line)?;
        writeln!(report, "{entry}").map_err(|e| e.to_string())?;
    }
    Ok(report)
}

fn main() {
    println!("{:?}", remove_nth_char("hello", 1));
    println!("{:?}", remove_nth_char("world", 5));
    println!("{:?}", remove_indices("rosetta", &[0, 3, 6]));
    println!("{:?}", remove_indices("rosetta", &[0, 42]));

    match format_report(&["hello 1", "grüßen 2", "abc 0"]) {
        Ok(report) => print!("{report}"),
        Err(err) => eprintln!("error: {err}"),
    }

    for bad in ["world 5", "oops", "abc x"] {
        match describe_command(bad) {
            Ok(entry) => println!("{entry}"),
            Err(err) => println!("{bad} -> rejected ({err})"),
        }
    }
}

