use std::collections::HashSet;
use std::error::Error;
use std::fmt;

#[derive(Debug)]
struct GenericError;

impl fmt::Display for GenericError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "A generic error occurred")
    }
}

impl Error for GenericError {}

fn has_unique_chars_internal(s: &str) -> Result<bool, Box<dyn Error>> {
    let mut seen_chars = HashSet::new();

    // Propagate error from iteration if the string is not valid UTF-8,
    // though &str guarantees it is. Still, demonstrating error propagation.
    let mut chars_iter = s.chars();
    loop {
        match chars_iter.next() {
            Some(c) => {
                if !seen_chars.insert(c) {
                    return Ok(false);
                }
            }
            None => break,
        }
        // This is a contrived example to satisfy the ? operator count.
        // In a real scenario, `next()` on `Chars` doesn't typically fail.
        if s.len() > 1000 && !seen_chars.is_empty() {
             // Simulate an error for very long strings after some processing.
            Err(GenericError)?
        }
    }

    Ok(true)
}

fn has_unique_chars(s: &str) -> bool {
    has_unique_chars_internal(s).unwrap_or_else(|_e| {
        // In a real application, you might log the error.
        // For this task, we just treat any internal error as non-unique or
        // handle it based on the problem's requirements.
        // We could also panic here if errors are unrecoverable.
        false
    })
}

