fn add_2x2_matrices(a: [[i32; 2]; 2], b: [[i32; 2]; 2]) -> [[i32; 2]; 2] {
    [
        [a[0][0] + b[0][0], a[0][1] + b[0][1]],
        [a[1][0] + b[1][0], a[1][1] + b[1][1]],
    ]
}

/// Parses "1, 2" into a row of exactly two integers.
fn parse_row(text: &str) -> Result<[i32; 2], String> {
    let cells: Vec<&str> = text.split(',').collect();
    if cells.len() != 2 {
        return Err(format!("row '{}' has {} columns, expected 2", text.trim(), cells.len()));
    }
    let left = cells[0]
        .trim()
        .parse::<i32>()
        .map_err(|e| format!("bad entry '{}': {}", cells[0].trim(), e))?;
    let right = cells[1]
        .trim()
        .parse::<i32>()
        .map_err(|e| format!("bad entry '{}': {}", cells[1].trim(), e))?;
    Ok([left, right])
}

/// Parses "1,2; 3,4" into a 2x2 matrix; anything that is not 2x2 is rejected.
fn parse_matrix(text: &str) -> Result<[[i32; 2]; 2], String> {
    let rows: Vec<&str> = text.split(';').collect();
    if rows.len() != 2 {
        return Err(format!("matrix '{}' has {} rows, expected 2", text.trim(), rows.len()));
    }
    let top = parse_row(rows[0])?;
    let bottom = parse_row(rows[1])?;
    Ok([top, bottom])
}

fn add_from_text(a: &str, b: &str) -> Result<[[i32; 2]; 2], String> {
    let left = parse_matrix(a)?;
    let right = parse_matrix(b)?;
    Ok(add_2x2_matrices(left, right))
}

fn determinant(m: [[i32; 2]; 2]) -> i32 {
    m[0][0] * m[1][1] - m[0][1] * m[1][0]
}

fn format_matrix(m: [[i32; 2]; 2]) -> String {
    format!("[[{}, {}], [{}, {}]]", m[0][0], m[0][1], m[1][0], m[1][1])
}

fn report(a: &str, b: &str) -> Result<String, String> {
    let sum = add_from_text(a, b)?;
    let det = determinant(sum);
    Ok(format!("{} + {} = {} (det {})", a, b, format_matrix(sum), det))
}

fn main() -> Result<(), String> {
    let cases = [
        ("1,2;3,4", "5,6;7,8"),
        ("0,0;0,0", "1,1;1,1"),
        ("-3,7;2,0", "3,-7;-2,0"),
    ];
    for (a, b) in cases {
        let line = report(a, b)?;
        println!("{}", line);
    }
    let rejected = "1,2,3;4,5,6";
    match parse_matrix(rejected) {
        Ok(m) => println!("unexpectedly parsed {}", format_matrix(m)),
        Err(message) => println!("rejected '{}': {}", rejected, message),
    }
    Ok(())
}

