use std::fmt::{self, Write as _};

#[derive(Debug)]
enum RuleError {
    MissingSeparator(String),
    MissingChar,
    NotSingleChar(String),
    Format(fmt::Error),
}

impl From<fmt::Error> for RuleError {
    fn from(e: fmt::Error) -> Self {
        RuleError::Format(e)
    }
}

impl fmt::Display for RuleError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            RuleError::MissingSeparator(line) => write!(f, "rule {:?} has no '|' separator", line),
            RuleError::MissingChar => write!(f, "rule specifies no character to remove"),
            RuleError::NotSingleChar(field) => write!(f, "{:?} is not a single character", field),
            RuleError::Format(e) => write!(f, "formatting failure: {}", e),
        }
    }
}

fn remove_char_all(s: &str, char_to_remove: char) -> String {
    s.chars().filter(|c| *c != char_to_remove).collect()
}

fn parse_char(field: &str) -> Result<char, RuleError> {
    let mut chars = field.chars();
    let wanted = chars.next().ok_or(RuleError::MissingChar)?;
    if chars.next().is_some() {
        return Err(RuleError::NotSingleChar(field.to_string()));
    }
    Ok(wanted)
}

fn parse_rule(line: &str) -> Result<(String, char), RuleError> {
    let (text, spec) = line
        .split_once('|')
        .ok_or_else(|| RuleError::MissingSeparator(line.to_string()))?;
    let wanted = parse_char(spec.trim())?;
    Ok((text.trim().to_string(), wanted))
}

fn build_report(lines: &[String]) -> Result<String, RuleError> {
    let mut out = String::new();
    for line in lines {
        let (text, wanted) = parse_rule(line)?;
        let stripped = remove_char_all(&text, wanted);
        writeln!(out, "{:?} without {:?} -> {:?}", text, wanted, stripped)?;
    }
    write!(out, "{} rule(s) applied", lines.len())?;
    Ok(out)
}

fn main() -> Result<(), RuleError> {
    let mut rules: Vec<String> = std::env::args().skip(1).collect();
    if rules.is_empty() {
        rules = vec!["banana | a".to_string(), "hello | z".to_string()];
    }
    println!("{}", build_report(&rules)?);
    Ok(())
}

