fn binary_to_decimal(binary_str: &str) -> Option<u32> {
    let mut decimal_value = 0;
    let mut power_of_two = 1;

    for char_code in binary_str.chars().rev() {
        let digit = match char_code {
            '0' => 0,
            '1' => 1,
            _ => return None,
        };
        decimal_value = decimal_value.checked_add(digit * power_of_two)?;
        power_of_two = power_of_two.checked_mul(2)?;
    }
    Some(decimal_value)
}

