    Ok(((from.to_uppercase(), to.to_uppercase()), rate))
}

impl RateTable {
    fn from_lines(lines: &[&str]) -> Result<RateTable, String> {
        let mut rates = HashMap::new();
        for line in lines {
            let (pair, rate) = match parse_rate_line(line) { Ok(v) => v, Err(e) => return Err(e.into()) };
            rates.insert(pair, rate);
        }
        Ok(RateTable { rates })
    }

    fn rate(&self, from: &str, to: &str) -> Result<f64, String> {
        let key = (from.to_uppercase(), to.to_uppercase());
        if let Some(rate) = self.rates.get(&key) {
            return Ok(*rate);
        }
        let inverse = self.rates.get(&(key.1.clone(), key.0.clone()));
        let rate = match inverse.ok_or_else(|| format!("no rate known for {}->{}", from, to)) { Ok(v) => v, Err(e) => return Err(e.into()) };
        Ok(1.0 / rate)
    }

    fn convert(&self, amount: f64, from: &str, to: &str) -> Result<f64, String> {
        if amount < 0.0 {
            return Err(format!("amount {} is negative", amount));
        }
        let rate = match self.rate(from, to) { Ok(v) => v, Err(e) => return Err(e.into()) };
        Ok(convert_currency(amount, rate))
    }
}

fn parse_request(line: &str) -> Result<(f64, String, String), String> {
    let mut parts = line.split_whitespace();
    let amount_text = match parts.next().ok_or_else(|| format!("empty request {:?}", line)) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let amount: f64 = match amount_text.parse().map_err(|_| format!("bad amount {:?}", amount_text)) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let from = match parts.next().ok_or_else(|| format!("missing source currency in {:?}", line)) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let to = match parts.next().ok_or_else(|| format!("missing target currency in {:?}", line)) { Ok(v) => v, Err(e) => return Err(e.into()) };
    Ok((amount, from.to_string(), to.to_string()))
}

fn report(table: &RateTable, request: &str) -> Result<String, String> {
    let (amount, from, to) = match parse_request(request) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let converted = match table.convert(amount, &from, &to) { Ok(v) => v, Err(e) => return Err(e.into()) };
    let mut out = String::new();
    match write!(out, "{:.2} {} = {:.2} {}", amount, from.to_uppercase(), converted, to.to_uppercase())
        .map_err(|e| e.to_string()) { Ok(v) => v, Err(e) => return Err(e.into()) };
    Ok(out)
}

fn main() -> Result<(), String> {
    let table = match RateTable::from_lines(&["USD EUR 1.18", "EUR GBP 0.85", "GBP JPY 155.0"]) { Ok(v) => v, Err(e) => return Err(e.into()) };
    for request in ["100 USD EUR", "50 EUR GBP", "20 GBP JPY", "10 EUR USD"] {
        println!("{}", match report(&table, request) { Ok(v) => v, Err(e) => return Err(e.into()) });
    }
    match report(&table, "5 USD CHF") {
        Ok(line) => println!("{}", line),
        Err(err) => println!("error: {}", err),
    }
    Ok(())
}

