fn char_to_ascii(c: char) -> Result<u8, std::num::TryFromIntError> {
    let s = c.to_string();
    let bytes = s.as_bytes();
    let first_byte = bytes.get(0).ok_or_else(|| {
        std::num::TryFromIntError::try_from(std::convert::Infallible).unwrap_err()
    })?;
