fn integer_power(base: u32, exponent: u32) -> Result<u32, &'static str> {
    if exponent == 0 {
        return Ok(1);
    }
    let mut result = 1;
    let mut current_base = base;
    let mut current_exponent = exponent;

    while current_exponent > 0 {
        if current_exponent % 2 == 1 {
            result = result.checked_mul(current_base).ok_or("Overflow occurred")?;
        }
        current_base = current_base.checked_mul(current_base).ok_or("Overflow occurred")?;
        current_exponent /= 2;
    }
    Ok(result)
}

fn main() -> Result<(), &'static str> {
    let p1 = integer_power(2, 3)?;
    println!("2^3 = {}", p1);

    let p2 = integer_power(5, 0)?;
    println!("5^0 = {}", p2);

    let p3 = integer_power(10, 1)?;
    println!("10^1 = {}", p3);

    let p4 = integer_power(3, 4)?;
    println!("3^4 = {}", p4);

    let p5 = integer_power(u32::MAX, 1)?;
    println!("MAX^1 = {}", p5);

    let p6 = integer_power(2, 31)?; // This should overflow
    println!("2^31 = {}", p6); // This line won't be reached if p6 overflows

    Ok(())
}

