use std::collections::HashSet;
use std::fmt::Write as _;
use std::num::ParseIntError;

#[derive(Debug)]
enum DataError {
    MissingSeparator(String),
    BadNumber(ParseIntError),
    Format(std::fmt::Error),
}

impl From<ParseIntError> for DataError {
    fn from(e: ParseIntError) -> Self {
        DataError::BadNumber(e)
    }
}

impl From<std::fmt::Error> for DataError {
    fn from(e: std::fmt::Error) -> Self {
        DataError::Format(e)
    }
}

fn find_common_elements(a: &[i32], b: &[i32]) -> Vec<i32> {
    let in_b: HashSet<i32> = b.iter().copied().collect();
    let mut seen = HashSet::new();
    let mut common = Vec::new();
    for value in a.iter().copied() {
        if in_b.contains(&value) && seen.insert(value) {
            common.push(value);
        }
    }
    common
}

fn parse_vector(spec: &str) -> Result<Vec<i32>, DataError> {
    let trimmed = spec.trim();
    if trimmed.is_empty() {
        return Ok(Vec::new());
    }
    let mut values = Vec::new();
    for token in trimmed.split(',') {
        values.push(match token.trim().parse::<i32>() {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        });
    }
    Ok(values)
}

fn split_pair(line: &str) -> Result<(&str, &str), DataError> {
    let halves = match line
        .split_once('|')
        .ok_or_else(|| DataError::MissingSeparator(line.to_string()))
    {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(halves)
}

fn common_from_line(line: &str) -> Result<Vec<i32>, DataError> {
    let (left, right) = match split_pair(line) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let a = match parse_vector(left) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let b = match parse_vector(right) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(find_common_elements(&a, &b))
}

fn render_line(line: &str) -> Result<String, DataError> {
    let common = match common_from_line(line) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let items: Vec<String> = common.iter().map(|v| v.to_string()).collect();
    let mut rendered = String::new();
    match write!(rendered, "{} => [{}]", line.trim(), items.join(", ")) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(rendered)
}

fn build_report(input: &str) -> Result<String, DataError> {
    let mut report = String::new();
    for line in input.lines().filter(|l| !l.trim().is_empty()) {
        let rendered = match render_line(line) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        match writeln!(report, "{}", rendered) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
    }
    Ok(report)
}

