use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum ScriptError {
    Number(ParseIntError),
    Syntax(String),
}

impl From<ParseIntError> for ScriptError {
    fn from(err: ParseIntError) -> Self {
        ScriptError::Number(err)
    }
}

impl fmt::Display for ScriptError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ScriptError::Number(e) => write!(f, "invalid integer: {}", e),
            ScriptError::Syntax(s) => write!(f, "invalid command: {}", s),
        }
    }
}

fn remove_first_matching(vec: &mut Vec<i32>, element: i32) -> Option<i32> {
    let index = vec.iter().position(|&x| x == element)?;
    Some(vec.remove(index))
}

fn remove_first_occurrence(vec: &mut Vec<i32>, element: i32) -> bool {
    remove_first_matching(vec, element).is_some()
}

fn parse_vector(text: &str) -> Result<Vec<i32>, ScriptError> {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return Ok(Vec::new());
    }
    let mut values = Vec::new();
    for field in trimmed.split(',') {
        values.push(field.trim().parse::<i32>()?);
    }
    Ok(values)
}

enum Command {
    Remove(i32),
    Push(i32),
}

fn parse_command(line: &str) -> Result<Command, ScriptError> {
    let text = line.trim();
    let (verb, arg) = text
        .split_once(' ')
        .ok_or_else(|| ScriptError::Syntax(text.to_string()))?;
    let value = arg.trim().parse::<i32>()?;
    match verb {
        "remove" => Ok(Command::Remove(value)),
        "push" => Ok(Command::Push(value)),
        other => Err(ScriptError::Syntax(other.to_string())),
    }
}

fn format_vector(vec: &[i32]) -> String {
    vec.iter().map(|v| v.to_string()).collect::<Vec<_>>().join(", ")
}

fn run_script(initial: &str, script: &str) -> Result<Vec<String>, ScriptError> {
    let mut vec = parse_vector(initial)?;
    let mut log = Vec::new();
    for line in script.lines().filter(|l| !l.trim().is_empty()) {
        let note = match parse_command(line)? {
            Command::Remove(value) => {
                format!("remove {} -> {}", value, remove_first_occurrence(&mut vec, value))
            }
            Command::Push(value) => {
                vec.push(value);
                format!("push {} -> true", value)
            }
        };
        log.push(format!("{}; vec = [{}]", note, format_vector(&vec)));
    }
    Ok(log)
}

fn main() -> Result<(), ScriptError> {
    for entry in run_script("1, 2, 3, 2", "remove 2\nremove 5\npush 7")? {
        println!("{}", entry);
    }
    println!("{}", run_script("1, 2", "remove 5")?.join("\n"));
    Ok(())
}

