use std::error::Error;
use std::fmt;
use std::io::{self, Read, Write};

#[derive(Debug)]
enum SpecError {
    MissingSeparator(String),
    BadLength(String),
    EmptyWord(String),
}

impl fmt::Display for SpecError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SpecError::MissingSeparator(line) => write!(f, "missing ':' in spec {:?}", line),
            SpecError::BadLength(text) => write!(f, "invalid maximum length {:?}", text),
            SpecError::EmptyWord(line) => write!(f, "empty word in list {:?}", line),
        }
    }
}

impl Error for SpecError {}

fn filter_strings_by_length(strings: &[String], max_len: usize) -> Vec<String> {
    strings
        .iter()
        .filter(|s| s.chars().count() <= max_len)
        .cloned()
        .collect()
}

fn parse_max_len(field: &str) -> Result<usize, SpecError> {
    let text = field.trim();
    let value = text
        .parse::<usize>()
        .map_err(|_| SpecError::BadLength(text.to_string()))?;
    Ok(value)
}

fn parse_word(field: &str, list: &str) -> Result<String, SpecError> {
    let word = field.trim();
    if word.is_empty() {
        return Err(SpecError::EmptyWord(list.to_string()));
    }
    Ok(word.to_string())
}

fn parse_words(list: &str) -> Result<Vec<String>, SpecError> {
    let mut words = Vec::new();
    for field in list.split(',') {
        words.push(parse_word(field, list)?);
    }
    Ok(words)
}

fn parse_spec(line: &str) -> Result<(usize, Vec<String>), SpecError> {
    let (head, tail) = line
        .split_once(':')
        .ok_or_else(|| SpecError::MissingSeparator(line.to_string()))?;
    let max_len = parse_max_len(head)?;
    Ok((max_len, parse_words(tail)?))
}

fn report_line(line: &str) -> Result<String, SpecError> {
    let (max_len, words) = parse_spec(line)?;
    let kept = filter_strings_by_length(&words, max_len);
    Ok(format!("<= {}: [{}]", max_len, kept.join(", ")))
}

fn write_report<W: Write>(out: &mut W, input: &str) -> Result<(), Box<dyn Error>> {
    for line in input.lines().filter(|l| !l.trim().is_empty()) {
        let report = report_line(line)?;
        writeln!(out, "{}", report)?;
    }
    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;
    let stdout = io::stdout();
    let mut out = stdout.lock();
    write_report(&mut out, &input)?;
    Ok(())
}

