fn sphere_volume(radius: f64) -> Result<f64, String> {
    if radius < 0.0 {
        return Err("Radius cannot be negative".to_string());
    }

    let radius_squared = radius.checked_mul(radius)
        .ok_or_else(|| "Radius squared overflowed".to_string())?;

    let radius_cubed = radius_squared.checked_mul(radius)
        .ok_or_else(|| "Radius cubed overflowed".to_string())?;

    let four_thirds = 4.0 / 3.0;

    let intermediate_product = four_thirds.checked_mul(std::f64::consts::PI)
        .ok_or_else(|| "Intermediate product overflowed".to_string())?;

    let volume = intermediate_product.checked_mul(radius_cubed)
        .ok_or_else(|| "Volume calculation overflowed".to_string())?;

    Ok(volume)
}

fn main() -> Result<(), String> {
    let r1 = 1.0;
    let v1 = sphere_volume(r1)?;
    println!("Volume of sphere with radius {}: {}", r1, v1);

    let r2 = 3.0;
    let v2 = sphere_volume(r2)?;
    println!("Volume of sphere with radius {}: {}", r2, v2);

    let r3 = -1.0;
    match sphere_volume(r3) {
        Ok(v) => println!("Volume of sphere with radius {}: {}", r3, v),
        Err(e) => println!("Error for radius {}: {}", r3, e),
    }

    let r4 = f64::MAX;
    match sphere_volume(r4) {
        Ok(v) => println!("Volume of sphere with radius {}: {}", r4, v),
