fn count_lines(text: &str) -> Result<usize, String> {
    let mut line_count = 0;
    let mut chars = text.chars().peekable();

    if text.is_empty() {
        return Ok(0);
    }

    loop {
        let Some(c) = chars.next() else { break; };
        if c == '\n' {
            line_count += 1;
        }

        let Some(_) = chars.peek() else { break; };
    }

    if !text.ends_with('\n') {
        line_count += 1;
    }

    Ok(line_count)
}

fn main() -> Result<(), String> {
    let lines1 = count_lines("hello\nworld")?;
