fn format_seconds(total_seconds: u32) -> Result<String, std::fmt::Error> {
    let hours = total_seconds / 3600;
    let remaining_seconds = total_seconds % 3600;
    let minutes = remaining_seconds / 60;
    let seconds = remaining_seconds % 60;

    let mut result = String::new();
    use std::io::Write; 

    write!(result, "{:02}", hours)?;
    write!(result, ":")?;
    write!(result, "{:02}", minutes)?;
    write!(result, ":")?;
    write!(result, "{:02}", seconds)?;

    Ok(result)
}

