use std::collections::HashMap;
use std::io::{self, Write};

fn get_from_map(map: &HashMap<String, String>, key: &str) -> Result<String, io::Error> {
    let output = if let Some(value) = map.get(key) {
        let value_string = value.to_string();
        io::stdout().write_all(b"Found value: ")?;
        io::stdout().write_all(value_string.as_bytes())?;
        io::stdout().write_all(b"\n")?;
        value_string
    } else {
        let default_value = "NOT_FOUND".to_string();
        io::stdout().write_all(b"Key not found, returning default: ")?;
        io::stdout().write_all(default_value.as_bytes())?;
        io::stdout().write_all(b"\n")?;
        default_value
    };
    Ok(output)
}

fn main() -> Result<(), io::Error> {
    let mut map = HashMap::new();
    map.insert("a".to_string(), "1".to_string());
    map.insert("b".to_string(), "2".to_string());

    let result1 = get_from_map(&map, "a")?;
    io::stdout().write_all(format!("Result for 'a': {}\n", result1).as_bytes())?;

    let result2 = get_from_map(&map, "c")?;
    io::stdout().write_all(format!("Result for 'c': {}\n", result2).as_bytes())?;

    let result3 = get_from_map(&map, "b")?;
    io::stdout().write_all(format!("Result for 'b': {}\n", result3).as_bytes())?;

    Ok(())
}

