fn product_of_elements(numbers: &Vec<i32>) -> Result<i32, String> {
    if numbers.is_empty() {
        return Ok(1);
    }

    let mut product = 1;
    for &num in numbers {
        product = product
            .checked_mul(num)
            .ok_or_else(|| format!("Overflow occurred when multiplying by {}", num))?;
    }
    Ok(product)
}

