use std::env;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Write};

fn grep_lines(lines: &Vec<String>, pattern: &str) -> Vec<String> {
    lines
        .iter()
        .filter(|line| line.contains(pattern))
        .cloned()
        .collect()
}

fn read_lines(path: &str) -> io::Result<Vec<String>> {
    let reader = BufReader::new(File::open(path)?);
    let mut lines = Vec::new();
    for line in reader.lines() {
        lines.push(line?);
    }
    Ok(lines)
}

fn grep_file(path: &str, pattern: &str) -> io::Result<Vec<String>> {
    let lines = read_lines(path)?;
    Ok(grep_lines(&lines, pattern))
}

struct Config {
    pattern: String,
    paths: Vec<String>,
    output: Option<String>,
    max_count: Option<usize>,
}

fn parse_args(args: Vec<String>) -> Result<Config, String> {
    let mut items = args.into_iter();
    let mut output = None;
    let mut max_count = None;
    let mut positional = Vec::new();
    while let Some(arg) = items.next() {
        if arg == "-o" {
            output = Some(items.next().ok_or("-o requires a file name")?);
        } else if arg == "-m" {
            let raw = items.next().ok_or("-m requires a number")?;
            max_count = Some(raw.parse::<usize>().map_err(|e| e.to_string())?);
        } else {
            positional.push(arg);
        }
    }
    let mut positional = positional.into_iter();
    let pattern = positional.next().ok_or("usage: grep [-o FILE] [-m N] PATTERN FILE...")?;
    let paths: Vec<String> = positional.collect();
    if paths.is_empty() {
        return Err("at least one input file is required".to_string());
    }
    Ok(Config { pattern, paths, output, max_count })
}

fn format_matches(path: &str, matches: &[String]) -> String {
    matches
        .iter()
        .map(|line| format!("{}:{}\n", path, line))
        .collect()
}

fn write_report(path: &str, text: &str) -> io::Result<()> {
    let mut file = File::create(path)?;
    file.write_all(text.as_bytes())?;
    Ok(())
}

fn run(config: &Config) -> Result<usize, String> {
    let mut report = String::new();
    let mut total = 0;
    for path in &config.paths {
        let mut matches = grep_file(path, &config.pattern)
            .map_err(|e| format!("{}: {}", path, e))?;
        if let Some(limit) = config.max_count {
            matches.truncate(limit);
        }
        total += matches.len();
        report.push_str(&format_matches(path, &matches));
    }
    match &config.output {
        Some(path) => write_report(path, &report).map_err(|e| format!("{}: {}", path, e))?,
        None => print!("{}", report),
    }
    Ok(total)
}

fn main() -> Result<(), String> {
    let config = parse_args(env::args().skip(1).collect())?;
    let total = run(&config)?;
    eprintln!("{} matching line(s) for \"{}\"", total, config.pattern);
    Ok(())
}

