use std::env;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum EvenError {
    BadSpec(String),
    Number(ParseIntError),
    Overflow,
}

impl fmt::Display for EvenError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            EvenError::BadSpec(s) => write!(f, "bad range specification: {}", s),
            EvenError::Number(e) => write!(f, "invalid number: {}", e),
            EvenError::Overflow => write!(f, "sum of even numbers overflowed u32"),
        }
    }
}

impl From<ParseIntError> for EvenError {
    fn from(e: ParseIntError) -> Self {
        EvenError::Number(e)
    }
}

fn generate_evens(n: u32) -> Vec<u32> {
    (0..=n).step_by(2).collect()
}

fn parse_range(spec: &str) -> Result<(u32, u32), EvenError> {
    let (low, high) = spec
        .split_once("..")
        .ok_or_else(|| EvenError::BadSpec(spec.to_string()))?;
    let start: u32 = low.trim().parse()?;
    let end: u32 = high.trim().parse()?;
    if start > end {
        return Err(EvenError::BadSpec(spec.to_string()));
    }
    Ok((start, end))
}

fn evens_in_range(spec: &str) -> Result<Vec<u32>, EvenError> {
    let (start, end) = parse_range(spec)?;
    Ok(generate_evens(end)
        .into_iter()
        .filter(|value| *value >= start)
        .collect())
}

fn sum_evens(evens: &[u32]) -> Result<u32, EvenError> {
    let mut total: u32 = 0;
    for value in evens {
        total = total.checked_add(*value).ok_or(EvenError::Overflow)?;
    }
    Ok(total)
}

fn format_line(spec: &str) -> Result<String, EvenError> {
    let evens = evens_in_range(spec)?;
    let total = sum_evens(&evens)?;
    let largest = match evens.last() {
        Some(value) => value.to_string(),
        None => String::from("none"),
    };
    Ok(format!("{:>10} -> {:?} (sum {}, largest {})", spec, evens, total, largest))
}

fn report(specs: &[&str]) -> Result<String, EvenError> {
    let mut out = String::new();
    for spec in specs {
        out.push_str(&format_line(spec)?);
        out.push('\n');
    }
    Ok(out)
}

fn main() -> Result<(), EvenError> {
    let args: Vec<String> = env::args().skip(1).collect();
    let specs: Vec<String> = if args.is_empty() {
        vec!["0..6".to_string(), "0..3".to_string(), "5..20".to_string()]
    } else {
        args
    };
    let borrowed: Vec<&str> = specs.iter().map(String::as_str).collect();
    print!("{}", report(&borrowed)?);
    Ok(())
}

