use std::fmt::Write;

/// Area of a triangle from its base and height.
fn triangle_area(base: f64, height: f64) -> f64 {
    0.5 * base * height
}

/// Parses one dimension, rejecting anything that cannot describe a triangle.
fn parse_dimension(label: &str, text: &str) -> Result<f64, String> {
    let trimmed = text.trim();
    let value: f64 = trimmed
        .parse()
        .map_err(|_| format!("{}: {:?} is not a number", label, trimmed))?;
    if !(value.is_finite() && value > 0.0) {
        return Err(format!("{}: expected a positive length, got {}", label, value));
    }
    Ok(value)
}

/// Splits and parses a `"base,height"` specification.
fn parse_pair(spec: &str) -> Result<(f64, f64), String> {
    let (base_text, height_text) = spec
        .split_once(',')
        .ok_or_else(|| format!("expected \"base,height\", got {:?}", spec))?;
    let base = parse_dimension("base", base_text)?;
    let height = parse_dimension("height", height_text)?;
    Ok((base, height))
}

fn area_from_spec(spec: &str) -> Result<f64, String> {
    let (base, height) = parse_pair(spec)?;
    Ok(triangle_area(base, height))
}

fn format_row(spec: &str) -> Result<String, String> {
    let (base, height) = parse_pair(spec)?;
    let area = triangle_area(base, height);
    Ok(format!("{:>8.2} {:>8.2} {:>10.2}", base, height, area))
}

fn total_area(specs: &[&str]) -> Result<f64, String> {
    let mut total = 0.0;
    for spec in specs {
        total += area_from_spec(spec)?;
    }
    Ok(total)
}

fn report(specs: &[&str]) -> Result<String, String> {
    let mut out = String::new();
    writeln!(out, "{:>8} {:>8} {:>10}", "base", "height", "area").map_err(|e| e.to_string())?;
    for spec in specs {
        let row = format_row(spec)?;
        writeln!(out, "{}", row).map_err(|e| e.to_string())?;
    }
    let total = total_area(specs)?;
    writeln!(out, "{:>26}", "----------").map_err(|e| e.to_string())?;
    writeln!(out, "total{:>21.2}", total).map_err(|e| e.to_string())?;
    Ok(out)
}

fn main() -> Result<(), String> {
    let specs = ["10.0,5.0", "7.0,4.0", "3.5,  12", "0.75,0.4"];
    let table = report(&specs)?;
    print!("{}", table);

    let single = area_from_spec("10.0,5.0")?;
    println!("triangle_area(10.0, 5.0) = {}", single);

    match area_from_spec("6.0,-2") {
        Ok(area) => println!("unexpected area {}", area),
        Err(message) => println!("rejected: {}", message),
    }
    Ok(())
}

