use rand::Rng;
use std::fmt;
use std::num::ParseIntError;

const NAMED: [(&str, (u8, u8, u8)); 6] = [
    ("black", (0, 0, 0)),
    ("white", (255, 255, 255)),
    ("red", (255, 0, 0)),
    ("green", (0, 128, 0)),
    ("blue", (0, 0, 255)),
    ("gold", (255, 215, 0)),
];

#[derive(Debug)]
enum ColorError {
    BadLength(usize),
    BadDigit(ParseIntError),
    UnknownName(String),
}

impl fmt::Display for ColorError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ColorError::BadLength(n) => write!(f, "expected 6 hex digits, got {}", n),
            ColorError::BadDigit(e) => write!(f, "invalid hex digit: {}", e),
            ColorError::UnknownName(n) => write!(f, "unknown color name: {}", n),
        }
    }
}

impl From<ParseIntError> for ColorError {
    fn from(e: ParseIntError) -> Self {
        ColorError::BadDigit(e)
    }
}

fn generate_random_rgb() -> (u8, u8, u8) {
    let mut rng = rand::thread_rng();
    (rng.gen_range(0..=255), rng.gen_range(0..=255), rng.gen_range(0..=255))
}

fn to_hex((r, g, b): (u8, u8, u8)) -> String {
    format!("#{:02X}{:02X}{:02X}", r, g, b)
}

fn parse_hex(text: &str) -> Result<(u8, u8, u8), ColorError> {
    let digits = text.trim().trim_start_matches('#');
    if digits.len() != 6 {
        return Err(ColorError::BadLength(digits.len()));
    }
    let r = match u8::from_str_radix(&digits[0..2], 16) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let g = match u8::from_str_radix(&digits[2..4], 16) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let b = match u8::from_str_radix(&digits[4..6], 16) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok((r, g, b))
}

fn named(name: &str) -> Result<(u8, u8, u8), ColorError> {
    NAMED
        .iter()
        .find(|(n, _)| *n == name)
        .map(|(_, c)| *c)
        .ok_or_else(|| ColorError::UnknownName(name.to_string()))
}

fn mix_hex(first: &str, second: &str) -> Result<String, ColorError> {
    let (r1, g1, b1) = match parse_hex(first) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let (r2, g2, b2) = match parse_hex(second) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let avg = |a: u8, b: u8| ((a as u16 + b as u16) / 2) as u8;
    Ok(to_hex((avg(r1, r2), avg(g1, g2), avg(b1, b2))))
}

fn luminance((r, g, b): (u8, u8, u8)) -> f64 {
    0.2126 * r as f64 + 0.7152 * g as f64 + 0.0722 * b as f64
}

fn nearest_named((r, g, b): (u8, u8, u8)) -> &'static str {
    let distance = |(nr, ng, nb): (u8, u8, u8)| {
        let d = |a: u8, x: u8| (a as i32 - x as i32).pow(2);
        d(r, nr) + d(g, ng) + d(b, nb)
    };
    let mut best = NAMED[0];
    for entry in NAMED.iter().skip(1) {
        if distance(entry.1) < distance(best.1) {
            best = *entry;
        }
    }
    best.0
}

fn contrast_with_named(hex: &str, name: &str) -> Result<f64, ColorError> {
    let sample = luminance(match parse_hex(hex) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });
    let target = luminance(match named(name) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });
    Ok((sample - target).abs() / 255.0)
}

fn describe(hex: &str) -> Result<String, ColorError> {
    let rgb = match parse_hex(hex) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let against_white = match contrast_with_named(hex, "white") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(format!(
        "{} -> ({}, {}, {}), closest to {}, contrast vs white {:.3}",
        hex, rgb.0, rgb.1, rgb.2, nearest_named(rgb), against_white
    ))
}

fn main() -> Result<(), ColorError> {
    let first = to_hex(generate_random_rgb());
    let second = to_hex(generate_random_rgb());
    println!("{}", match describe(&first) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });
    println!("{}", match describe(&second) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });
    let blended = match mix_hex(&first, &second) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("blend: {}", match describe(&blended) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });
    println!("gold reference: {}", to_hex(match named("gold") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }));
    Ok(())
}

