fn is_alphanumeric(s: &str) -> Result<bool, std::io::Error> {
    if s.is_empty() {
        return Ok(true);
    }

    for c in s.chars() {
        if !c.is_alphanumeric() {
            return Ok(false);
        }
    }
    Ok(true)
}

fn main() -> Result<(), std::io::Error> {
    println!("{}", is_alphanumeric("HelloWorld123")?);
    println!("{}", is_alphanumeric("Hello World!")?);
    println!("{}", is_alphanumeric("")?);
    println!("{}", is_alphanumeric("a_b")?);
    println!("{}", is_alphanumeric("123")?);
    let result = is_alphanumeric("test")?;
    if result {
        println!("'test' is alphanumeric.");
    } else {
        println!("'test' is not alphanumeric.");
    }
    Ok(())
}

