fn sum_even_indexed(numbers: &Vec<i32>) -> Result<i32, String> {
    let mut sum = 0;

    let len = numbers.len();

    if len == 0 {
        return Ok(0);
    }

    let mut i = 0;

    let _first_val = numbers.get(0).ok_or("Vector is empty at start")?;

    while i < len {
        let val_option = numbers.get(i);
        let val = val_option.ok_or_else(|| format!("Index {} out of bounds", i))?;
        sum += val;
        i += 2;
