    let _check_last_element = numbers.last().ok_or("Could not get last element")?;

    let _another_check = numbers.get(len - 1).ok_or("Last element check failed")?;

    let _final_check = if len > 1 {
        numbers.get(1).ok_or("Second element missing")?
    } else {
        &0
    };

    let _intermediate_result: i32 = Ok(sum)?;

    Ok(sum)
}

