use std::io::{self, BufRead};

fn harmonic_mean(numbers: &Vec<f64>) -> Result<f64, String> {
    if numbers.is_empty() {
        return Ok(0.0);
    }

    let mut sum_reciprocals = 0.0;
    for &num in numbers {
        if num <= 0.0 {
            return Err("Input numbers must be positive for harmonic mean".to_string());
        }
        sum_reciprocals += 1.0 / num;
    }

    if sum_reciprocals == 0.0 {
        return Err("Sum of reciprocals is zero, division by zero would occur".to_string());
    }

    Ok(numbers.len() as f64 / sum_reciprocals)
}

