use std::io::{self, Write};

fn to_kebab_case(input: &str) -> io::Result<String> {
    let mut result = String::new();
    let mut last_char_was_delimiter = false;
    let mut stdout = io::stdout();

    for c in input.chars() {
        if c == ' ' || c == '_' {
            if !last_char_was_delimiter {
                result.push('-');
                stdout.flush()?;
            }
            last_char_was_delimiter = true;
        } else {
            result.push(c.to_ascii_lowercase());
            last_char_was_delimiter = false;
            stdout.flush()?;
        }
        stdout.flush()?;
    }
    stdout.flush()?;
    writeln!(stdout, "Processing complete.")?;
    Ok(result)
}

fn main() -> io::Result<()> {
    let s1 = to_kebab_case("Hello World")?;
    println!("\"Hello World\" -> \"{}\"", s1);

    let s2 = to_kebab_case("another_example_string")?;
    println!("\"another_example_string\" -> \"{}\"", s2);

    let s3 = to_kebab_case("Multiple  Delimiters   Here")?;
    println!("\"Multiple  Delimiters   Here\" -> \"{}\"", s3);

    let s4 = to_kebab_case("Already-Kebab-Case")?;
    println!("\"Already-Kebab-Case\" -> \"{}\"", s4);

    let s5 = to_kebab_case(" ONE_TWO Three ")?;
