use std::fmt;

#[derive(Debug)]
enum HttpError {
    StatusOutOfRange(u16),
    UnknownStatus(u16),
    MissingBody(String),
    MissingHeader(String),
    BadLength(String),
    Malformed,
    LengthMismatch { declared: usize, actual: usize },
}

impl fmt::Display for HttpError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            HttpError::StatusOutOfRange(c) => write!(f, "status {} is not a valid HTTP code", c),
            HttpError::UnknownStatus(c) => write!(f, "no reason phrase known for status {}", c),
            HttpError::MissingBody(d) => write!(f, "directive {:?} has no body", d),
            HttpError::MissingHeader(h) => write!(f, "response lacks header {}", h),
            HttpError::BadLength(v) => write!(f, "Content-Length {:?} is not a number", v),
            HttpError::Malformed => write!(f, "response has no header/body separator"),
            HttpError::LengthMismatch { declared, actual } => {
                write!(f, "declared {} bytes, body has {}", declared, actual)
            }
        }
    }
}

fn validate_status(code: u16) -> Result<u16, HttpError> {
    if (100..600).contains(&code) {
        Ok(code)
    } else {
        Err(HttpError::StatusOutOfRange(code))
    }
}

fn reason_phrase(code: u16) -> Result<&'static str, HttpError> {
    match validate_status(code)? {
        200 => Ok("OK"),
        201 => Ok("Created"),
        204 => Ok("No Content"),
        400 => Ok("Bad Request"),
        404 => Ok("Not Found"),
        500 => Ok("Internal Server Error"),
        other => Err(HttpError::UnknownStatus(other)),
    }
}

fn build_response(code: u16, body: &str) -> Result<String, HttpError> {
    let phrase = reason_phrase(code)?;
    Ok(format!(
        "HTTP/1.1 {} {}\r\nContent-Type: text/plain\r\nContent-Length: {}\r\n\r\n{}",
        code,
        phrase,
        body.len(),
        body
    ))
}

fn build_http_response(status_code: u16, body: &str) -> String {
    build_response(status_code, body).unwrap_or_else(|_| {
        format!(
            "HTTP/1.1 {} Unknown Status\r\nContent-Type: text/plain\r\nContent-Length: {}\r\n\r\n{}",
            status_code,
            body.len(),
            body
        )
    })
}

fn parse_directive(directive: &str) -> Result<(u16, &str), HttpError> {
    let (head, body) = directive
        .split_once(' ')
        .ok_or_else(|| HttpError::MissingBody(directive.to_string()))?;
    let code: u16 = head
        .parse()
        .map_err(|_| HttpError::MissingBody(directive.to_string()))?;
    Ok((validate_status(code)?, body))
}

fn respond_to_directive(directive: &str) -> Result<String, HttpError> {
    let (code, body) = parse_directive(directive)?;
    Ok(build_http_response(code, body))
}

fn header_value<'a>(response: &'a str, name: &str) -> Result<&'a str, HttpError> {
    let prefix = format!("\r\n{}: ", name);
    let start = response
        .find(&prefix)
        .ok_or_else(|| HttpError::MissingHeader(name.to_string()))?
        + prefix.len();
    let rest = &response[start..];
    let end = rest.find("\r\n").ok_or(HttpError::Malformed)?;
    Ok(&rest[..end])
}

fn content_length(response: &str) -> Result<usize, HttpError> {
    let raw = header_value(response, "Content-Length")?;
    raw.parse().map_err(|_| HttpError::BadLength(raw.to_string()))
}

fn body_of(response: &str) -> Result<&str, HttpError> {
    let split = response.find("\r\n\r\n").ok_or(HttpError::Malformed)?;
    Ok(&response[split + 4..])
}

fn check_response(response: &str) -> Result<usize, HttpError> {
    let declared = content_length(response)?;
    let actual = body_of(response)?.len();
    if declared != actual {
        return Err(HttpError::LengthMismatch { declared, actual });
    }
    Ok(declared)
}

fn run(directives: &[&str]) -> Result<(), HttpError> {
    for directive in directives {
        let response = respond_to_directive(directive)?;
        let len = check_response(&response)?;
        println!("{:?} ({} body bytes)", response, len);
    }
    Ok(())
}

fn main() {
    let directives = ["200 OK", "404 Not Found", "500 Internal Server Error"];
    if let Err(err) = run(&directives) {
        eprintln!("error: {}", err);
    }
}

