        body.len(),
        body
    ))
}

fn build_http_response(status_code: u16, body: &str) -> String {
    build_response(status_code, body).unwrap_or_else(|_| {
        format!(
            "HTTP/1.1 {} Unknown Status\r\nContent-Type: text/plain\r\nContent-Length: {}\r\n\r\n{}",
            status_code,
            body.len(),
            body
        )
    })
}

fn parse_directive(directive: &str) -> Result<(u16, &str), HttpError> {
    let (head, body) = match directive
        .split_once(' ')
        .ok_or_else(|| HttpError::MissingBody(directive.to_string())) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let code: u16 = match head
        .parse()
        .map_err(|_| HttpError::MissingBody(directive.to_string())) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok((match validate_status(code) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }, body))
}

fn respond_to_directive(directive: &str) -> Result<String, HttpError> {
    let (code, body) = match parse_directive(directive) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(build_http_response(code, body))
}

fn header_value<'a>(response: &'a str, name: &str) -> Result<&'a str, HttpError> {
    let prefix = format!("\r\n{}: ", name);
    let start = match response
        .find(&prefix)
        .ok_or_else(|| HttpError::MissingHeader(name.to_string())) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }
        + prefix.len();
    let rest = &response[start..];
    let end = match rest.find("\r\n").ok_or(HttpError::Malformed) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(&rest[..end])
}

fn content_length(response: &str) -> Result<usize, HttpError> {
    let raw = match header_value(response, "Content-Length") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    raw.parse().map_err(|_| HttpError::BadLength(raw.to_string()))
}

fn body_of(response: &str) -> Result<&str, HttpError> {
    let split = match response.find("\r\n\r\n").ok_or(HttpError::Malformed) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(&response[split + 4..])
}

fn check_response(response: &str) -> Result<usize, HttpError> {
    let declared = match content_length(response) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let actual = match body_of(response) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }.len();
    if declared != actual {
        return Err(HttpError::LengthMismatch { declared, actual });
    }
    Ok(declared)
}

fn run(directives: &[&str]) -> Result<(), HttpError> {
    for directive in directives {
        let response = match respond_to_directive(directive) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        let len = match check_response(&response) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        println!("{:?} ({} body bytes)", response, len);
    }
    Ok(())
}

fn main() {
    let directives = ["200 OK", "404 Not Found", "500 Internal Server Error"];
    if let Err(err) = run(&directives) {
        eprintln!("error: {}", err);
    }
}

