use std::collections::HashSet;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum InputError {
    Number(ParseIntError),
    MissingSeparator(String),
}

impl fmt::Display for InputError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            InputError::Number(e) => write!(f, "bad integer: {}", e),
            InputError::MissingSeparator(line) => write!(f, "missing ';' in {:?}", line),
        }
    }
}

impl From<ParseIntError> for InputError {
    fn from(e: ParseIntError) -> Self {
        InputError::Number(e)
    }
}

fn parse_vector(spec: &str) -> Result<Vec<i32>, InputError> {
    let trimmed = spec.trim();
    if trimmed.is_empty() {
        return Ok(Vec::new());
    }
    let mut values = Vec::new();
    for token in trimmed.split(',') {
        let value: i32 = token.trim().parse()?;
        values.push(value);
    }
    Ok(values)
}

fn vector_intersection(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    let lookup: HashSet<i32> = second.iter().copied().collect();
    let mut emitted: HashSet<i32> = HashSet::new();
    let mut common = Vec::new();
    for &value in first {
        if lookup.contains(&value) && emitted.insert(value) {
            common.push(value);
        }
    }
    common
}

fn intersect_specs(left: &str, right: &str) -> Result<Vec<i32>, InputError> {
    let first = parse_vector(left)?;
    let second = parse_vector(right)?;
    Ok(vector_intersection(&first, &second))
}

fn format_vector(values: &[i32]) -> String {
    let parts: Vec<String> = values.iter().map(|v| v.to_string()).collect();
    format!("[{}]", parts.join(", "))
}

fn describe_pair(line: &str) -> Result<String, InputError> {
    let (left, right) = line
        .split_once(';')
        .ok_or_else(|| InputError::MissingSeparator(line.to_string()))?;
    let common = intersect_specs(left, right)?;
    let shown = format_vector(&common);
    Ok(format!("{} n {} = {}", left.trim(), right.trim(), shown))
}

fn report(lines: &[&str]) -> Result<Vec<String>, InputError> {
    let mut rows = Vec::with_capacity(lines.len());
    for line in lines {
        rows.push(describe_pair(line)?);
    }
    Ok(rows)
}

fn main() -> Result<(), InputError> {
    let cases = ["1, 2, 3; 2, 3, 4", "1, 1, 2; 1, 3", "10, 20; 30, 40", "4, 5;"];
    for row in report(&cases)? {
        println!("{}", row);
    }
    let shared = intersect_specs("5, 6, 7, 6", "7, 8, 5")?;
    println!("shared count: {}", shared.len());
    Ok(())
}

