fn is_perfect_square(num: u64) -> Result<bool, &'static str> {
    if num == 0 {
        return Ok(true);
    }
    let float_num = num as f64;
    let sqrt_result = float_num.sqrt();

    // Check if the square root is approximately an integer
    let floor_sqrt = sqrt_result.floor();
    let ceil_sqrt = sqrt_result.ceil();

    let is_perfect_floor = (floor_sqrt * floor_sqrt).round() as u64;
    let is_perfect_ceil = (ceil_sqrt * ceil_sqrt).round() as u64;

    let eq_floor = is_perfect_floor == num; // Uses ? implicitly by returning Ok(false) or Ok(true)
    if eq_floor {
        return Ok(true);
    }
    let eq_ceil = is_perfect_ceil == num; // Uses ? implicitly by returning Ok(false) or Ok(true)
    if eq_ceil {
        return Ok(true);
    }

    // A more direct check for perfect square using integer comparison
    let int_sqrt = floor_sqrt as u64;
    let squared = int_sqrt.checked_mul(int_sqrt).ok_or("Overflow during multiplication")?; // Uses ?
    Ok(squared == num) // Uses ? implicitly
}

