use std::collections::VecDeque;

#[derive(Debug)]
enum Command {
    Push(i32),
    Pop,
    Peek,
    Sum2,
}

fn peek_queue(q: &VecDeque<i32>) -> Option<&i32> {
    q.front()
}

fn next_two_sum(q: &VecDeque<i32>) -> Option<i32> {
    let first = peek_queue(q)?;
    let second = q.get(1)?;
    Some(*first + *second)
}

fn describe_front(q: &VecDeque<i32>) -> Option<String> {
    let front = peek_queue(q)?;
    Some(format!("front is {} ({} element(s) queued)", front, q.len()))
}

fn parse_command(line: &str) -> Result<Command, String> {
    let mut parts = line.split_whitespace();
    let head = parts.next().ok_or_else(|| format!("empty command: {:?}", line))?;
    match head {
        "push" => {
            let arg = parts.next().ok_or_else(|| "push needs an argument".to_string())?;
            let value = arg.parse::<i32>().map_err(|e| format!("bad number {:?}: {}", arg, e))?;
            Ok(Command::Push(value))
        }
        "pop" => Ok(Command::Pop),
        "peek" => Ok(Command::Peek),
        "sum2" => Ok(Command::Sum2),
        other => Err(format!("unknown command {:?}", other)),
    }
}

fn apply(q: &mut VecDeque<i32>, cmd: Command) -> Result<String, String> {
    match cmd {
        Command::Push(value) => {
            q.push_back(value);
            Ok(format!("pushed {}", value))
        }
        Command::Pop => {
            let value = q.pop_front().ok_or_else(|| "pop on empty queue".to_string())?;
            Ok(format!("popped {}", value))
        }
        Command::Peek => Ok(describe_front(q).unwrap_or_else(|| "queue is empty".to_string())),
        Command::Sum2 => {
            let sum = next_two_sum(q).ok_or_else(|| "sum2 needs two elements".to_string())?;
            Ok(format!("sum of first two is {}", sum))
        }
    }
}

fn run_script(script: &str) -> Result<Vec<String>, String> {
    let mut queue: VecDeque<i32> = VecDeque::new();
    let mut log = Vec::new();
    for line in script.lines().filter(|l| !l.trim().is_empty()) {
        let cmd = parse_command(line.trim())?;
        log.push(apply(&mut queue, cmd)?);
    }
    let tail = describe_front(&queue).ok_or_else(|| "script drained the queue".to_string())?;
    log.push(tail);
    Ok(log)
}

