use std::fmt;
use std::num::ParseFloatError;

#[derive(Debug)]
enum GeomError {
    BadNumber(ParseFloatError),
    Shape(String),
}

impl fmt::Display for GeomError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            GeomError::BadNumber(e) => write!(f, "invalid coordinate: {e}"),
            GeomError::Shape(s) => write!(f, "malformed input: {s}"),
        }
    }
}

impl From<ParseFloatError> for GeomError {
    fn from(e: ParseFloatError) -> Self {
        GeomError::BadNumber(e)
    }
}

fn parse_coord(text: &str) -> Result<f64, GeomError> {
    let value: f64 = text.trim().parse()?;
    if value.is_finite() {
        Ok(value)
    } else {
        Err(GeomError::Shape(format!("coordinate is not finite: {text}")))
    }
}

fn parse_point(text: &str) -> Result<(f64, f64), GeomError> {
    let body = text.trim().trim_start_matches('(').trim_end_matches(')');
    let (left, right) = body
        .split_once(',')
        .ok_or_else(|| GeomError::Shape(format!("point needs two coordinates: {text}")))?;
    let x = parse_coord(left)?;
    let y = parse_coord(right)?;
    Ok((x, y))
}

fn parse_segment(spec: &str) -> Result<((f64, f64), (f64, f64)), GeomError> {
    let (head, tail) = spec
        .split_once("->")
        .ok_or_else(|| GeomError::Shape(format!("segment needs 'a -> b': {spec}")))?;
    let start = parse_point(head)?;
    let end = parse_point(tail)?;
    Ok((start, end))
}

fn calculate_slope(x1: f64, y1: f64, x2: f64, y2: f64) -> f64 {
    let dx = x2 - x1;
    if dx == 0.0 {
        if y2 >= y1 {
            f64::INFINITY
        } else {
            f64::NEG_INFINITY
        }
    } else {
        (y2 - y1) / dx
    }
}

fn equation_of(start: (f64, f64), slope: f64) -> String {
    if slope.is_finite() {
        let intercept = start.1 - slope * start.0;
        format!("y = {slope:.3}x + {intercept:.3}")
    } else {
        format!("x = {:.3}", start.0)
    }
}

fn describe_line(spec: &str) -> Result<String, GeomError> {
    let (start, end) = parse_segment(spec)?;
    let slope = calculate_slope(start.0, start.1, end.0, end.1);
    let label = if slope.is_finite() {
        format!("slope {slope}")
    } else {
        format!("vertical ({slope})")
    };
    Ok(format!("{spec:<22} {label:<20} {}", equation_of(start, slope)))
}

fn report(specs: &[&str]) -> Result<String, GeomError> {
    let mut out = String::new();
    for spec in specs {
        out.push_str(&describe_line(spec)?);
        out.push('\n');
    }
    Ok(out)
}

fn run() -> Result<(), GeomError> {
    let specs = ["(1,1) -> (3,5)", "(0,0) -> (4,0)", "(2,7) -> (2,-3)"];
    print!("{}", report(&specs)?);
    println!("direct: {}", calculate_slope(1.0, 1.0, 3.0, 5.0));
    println!("{}", describe_line("(1,1) -> (1,5)")?);
    Ok(())
}

fn main() {
    if let Err(e) = run() {
        eprintln!("error: {e}");
        std::process::exit(1);
    }
}

