fn to_binary_string(n: u32) -> Result<String, std::fmt::Error> {
    let mut num = n;
    if num == 0 {
        return Ok("0".to_string());
    }
    let mut chars = Vec::new();
    while num > 0 {
        let bit = num % 2;
        let c = std::char::from_digit(bit, 10).ok_or_else(|| {
            std::fmt::Error
        })?;
        chars.push(c);
        num /= 2;
    }
    chars.reverse();
    let s: String = chars.into_iter().collect();
    Ok(s)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let five_binary = to_binary_string(5)?;
    println!("5 in binary: {}", five_binary);

    let ten_binary = to_binary_string(10)?;
    println!("10 in binary: {}", ten_binary);

    let zero_binary = to_binary_string(0)?;
    println!("0 in binary: {}", zero_binary);

    let max_binary = to_binary_string(u32::MAX)?;
    println!("u32::MAX in binary: {}", max_binary);

    let large_num = 123456789;
    let large_binary = to_binary_string(large_num)?;
    println!("{} in binary: {}", large_num, large_binary);

    Ok(())
}

