fn to_title_case(s: &str) -> Result<String, std::io::Error> {
    let mut result = String::new();
    let mut capitalize_next = true;

    for c in s.chars() {
        if c.is_whitespace() {
            result.push(c);
            capitalize_next = true;
        } else {
            if capitalize_next {
                let upper_char = c.to_uppercase().next().ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidData, "Failed to uppercase character"))?;
                result.push(upper_char);
                capitalize_next = false;
            } else {
                let lower_char = c.to_lowercase().next().ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidData, "Failed to lowercase character"))?;
                result.push(lower_char);
            }
        }
    }
    Ok(result)
}

