#[derive(Debug)]
enum Op {
    Add,
    Sub,
    Mul,
    Div,
}

#[derive(Debug)]
enum Token {
    Num(i32),
    Operator(Op),
}

/// Pops the top element of the stack, or `None` if the stack is empty.
fn pop_stack(stack: &mut Vec<i32>) -> Option<i32> {
    stack.pop()
}

/// Pops two operands, returning them in the order (left, right).
fn pop_two(stack: &mut Vec<i32>) -> Option<(i32, i32)> {
    let right = pop_stack(stack)?;
    let left = pop_stack(stack)?;
    Some((left, right))
}

/// Applies a binary operator to the top two values of the stack.
fn apply_op(stack: &mut Vec<i32>, op: &Op) -> Option<i32> {
    let (left, right) = pop_two(stack)?;
    match op {
        Op::Add => left.checked_add(right),
        Op::Sub => left.checked_sub(right),
        Op::Mul => left.checked_mul(right),
        Op::Div => left.checked_div(right),
    }
}

fn parse_token(tok: &str) -> Result<Token, String> {
    match tok {
        "+" => Ok(Token::Operator(Op::Add)),
        "-" => Ok(Token::Operator(Op::Sub)),
        "*" => Ok(Token::Operator(Op::Mul)),
        "/" => Ok(Token::Operator(Op::Div)),
        num => {
            let n = num.parse::<i32>().map_err(|e| format!("bad token {:?}: {}", num, e))?;
            Ok(Token::Num(n))
        }
    }
}

fn eval_rpn(expr: &str) -> Result<i32, String> {
    let mut stack: Vec<i32> = Vec::new();
    for tok in expr.split_whitespace() {
        let token = parse_token(tok)?;
        match token {
            Token::Num(n) => stack.push(n),
            Token::Operator(op) => {
                let value = apply_op(&mut stack, &op)
                    .ok_or_else(|| format!("operator {:?} has no valid operands", op))?;
                stack.push(value);
            }
        }
    }
    let result = pop_stack(&mut stack).ok_or_else(|| "empty expression".to_string())?;
    if stack.is_empty() {
        Ok(result)
    } else {
        Err(format!("{} leftover operand(s)", stack.len()))
    }
}

fn summarize(exprs: &[&str]) -> Result<String, String> {
    let mut values = Vec::with_capacity(exprs.len());
    for expr in exprs {
        values.push(eval_rpn(expr)?);
    }
    let total: i32 = values.iter().sum();
    Ok(format!("values {:?}, total {}", values, total))
}

