use std::fmt;

#[derive(Debug)]
enum ConvError {
    NotANumber(String),
    Negative(f64),
    MissingFootMark(String),
}

impl fmt::Display for ConvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConvError::NotANumber(s) => write!(f, "cannot read {:?} as a number", s),
            ConvError::Negative(v) => write!(f, "length {} is negative", v),
            ConvError::MissingFootMark(s) => write!(f, "no foot mark in {:?}", s),
        }
    }
}

fn inches_to_cm(inches: f64) -> f64 {
    inches * 2.54
}

fn parse_inches(text: &str) -> Result<f64, ConvError> {
    let trimmed = text.trim().trim_end_matches("in").trim_end_matches('"').trim();
    let value: f64 = trimmed
        .parse()
        .map_err(|_| ConvError::NotANumber(trimmed.to_string()))?;
    if value < 0.0 {
        return Err(ConvError::Negative(value));
    }
    Ok(value)
}

fn parse_feet_inches(text: &str) -> Result<f64, ConvError> {
    let (feet_part, inch_part) = text
        .split_once('\'')
        .ok_or_else(|| ConvError::MissingFootMark(text.to_string()))?;
    let feet = parse_inches(feet_part)?;
    let inches = if inch_part.trim().is_empty() {
        0.0
    } else {
        parse_inches(inch_part)?
    };
    Ok(feet * 12.0 + inches)
}

fn parse_length(text: &str) -> Result<f64, ConvError> {
    if text.contains('\'') {
        parse_feet_inches(text)
    } else {
        parse_inches(text)
    }
}

fn convert_line(text: &str) -> Result<String, ConvError> {
    let inches = parse_length(text)?;
    Ok(format!("{:>8} in = {:8.2} cm", text.trim(), inches_to_cm(inches)))
}

fn convert_all(lines: &[&str]) -> Result<Vec<String>, ConvError> {
    let mut out = Vec::with_capacity(lines.len());
    for line in lines {
        out.push(convert_line(line)?);
    }
    Ok(out)
}

fn total_cm(lines: &[&str]) -> Result<f64, ConvError> {
    let mut sum = 0.0;
    for line in lines {
        sum += inches_to_cm(parse_length(line)?);
    }
    Ok(sum)
}

fn main() -> Result<(), ConvError> {
    println!("{}", inches_to_cm(1.0));
    println!("{}", inches_to_cm(10.0));

    let inputs = ["1.0", "10.0", "36 in", "5'11\"", "2'"];
    for row in convert_all(&inputs)? {
        println!("{}", row);
    }
    println!("total = {:.2} cm", total_cm(&inputs)?);

    let doorway = parse_length("6'8\"")?;
    println!("doorway: {:.1} cm", inches_to_cm(doorway));
    Ok(())
}

