use std::fmt;

#[derive(Debug)]
enum ZipError {
    WrongLength(usize),
    NotDigits(String),
    MissingField(&'static str),
    BadPlusFour(String),
}

impl fmt::Display for ZipError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ZipError::WrongLength(n) => write!(f, "expected 5 characters, found {}", n),
            ZipError::NotDigits(s) => write!(f, "'{}' contains non-digit characters", s),
            ZipError::MissingField(name) => write!(f, "record is missing the {} field", name),
            ZipError::BadPlusFour(s) => write!(f, "'{}' is not a valid ZIP+4 code", s),
        }
    }
}

const REGIONS: [&str; 10] = [
    "Northeast (CT, MA, ME, NH, NJ, PR, RI, VT)",
    "Mid-Atlantic (DE, NY, PA)",
    "Southeast (DC, MD, NC, SC, VA, WV)",
    "Deep South (AL, FL, GA, MS, TN)",
    "Midwest (IN, KY, MI, OH)",
    "Upper Midwest (IA, MN, MT, ND, SD, WI)",
    "Central Plains (IL, KS, MO, NE)",
    "South Central (AR, LA, OK, TX)",
    "Mountain (AZ, CO, ID, NM, NV, UT, WY)",
    "Pacific (AK, CA, HI, OR, WA)",
];

fn digits_only(s: &str) -> Result<(), ZipError> {
    if s.chars().all(|c| c.is_ascii_digit()) {
        Ok(())
    } else {
        Err(ZipError::NotDigits(s.to_string()))
    }
}

fn parse_zip(s: &str) -> Result<u32, ZipError> {
    if s.chars().count() != 5 {
        return Err(ZipError::WrongLength(s.chars().count()));
    }
    digits_only(s)?;
    s.parse::<u32>().map_err(|_| ZipError::NotDigits(s.to_string()))
}

fn is_valid_us_zip(s: &str) -> bool {
    parse_zip(s).is_ok()
}

fn parse_zip_plus_four(s: &str) -> Result<(u32, u32), ZipError> {
    let (head, tail) = s.split_once('-').ok_or_else(|| ZipError::BadPlusFour(s.to_string()))?;
    let zip = parse_zip(head)?;
    if tail.chars().count() != 4 {
        return Err(ZipError::BadPlusFour(s.to_string()));
    }
    digits_only(tail)?;
    let ext = tail.parse::<u32>().map_err(|_| ZipError::BadPlusFour(s.to_string()))?;
    Ok((zip, ext))
}

fn region_for(code: u32) -> &'static str {
    REGIONS[(code / 10000) as usize]
}

fn describe(line: &str) -> Result<String, ZipError> {
    let (city, raw) = line.split_once(',').ok_or(ZipError::MissingField("zip"))?;
    let code = parse_zip(raw.trim())?;
    Ok(format!("{:<12} {:05} -> {}", city.trim(), code, region_for(code)))
}

fn summarize(lines: &[&str]) -> Result<String, ZipError> {
    let mut report = String::new();
    for line in lines {
        report.push_str(&describe(line)?);
        report.push('\n');
    }
    Ok(report)
}

fn main() {
    for candidate in ["12345", "12345-6789", "0210", "9021O", "90210"] {
        println!("is_valid_us_zip({:?}) = {}", candidate, is_valid_us_zip(candidate));
    }
    match parse_zip_plus_four("12345-6789") {
        Ok((zip, ext)) => println!("ZIP+4 parsed: {:05} extension {:04}", zip, ext),
        Err(e) => println!("ZIP+4 error: {}", e),
    }
    for batch in [
        ["Boston, 02108", "Austin, 78701"],
        ["Seattle, 98101", "Nowhere, 1234"],
    ] {
        match summarize(&batch) {
            Ok(report) => print!("{}", report),
            Err(e) => println!("report failed: {}", e),
        }
    }
}

