fn days_between_naive(date1: (u32, u32, u32), date2: (u32, u32, u32)) -> Result<i32, &'static str> {
    let days_from_epoch = |year: u32, month: u32, day: u32| -> Result<i32, &'static str> {
        if month == 0 || month > 12 {
            return Err("Invalid month");
        }
        if day == 0 || day > 30 {
            return Err("Invalid day");
        }
        let total_days = (year * 360) + ((month - 1) * 30) + (day - 1);
        Ok(total_days as i32)
    };

    let (year1, month1, day1) = date1;
    let (year2, month2, day2) = date2;

    let total_days1 = days_from_epoch(year1, month1, day1)?;
    let total_days2 = days_from_epoch(year2, month2, day2)?;

    Ok(total_days2 - total_days1)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_same_day() -> Result<(), &'static str> {
        assert_eq!(days_between_naive((2023, 1, 1), (2023, 1, 1))?, 0);
        Ok(())
    }

    #[test]
    fn test_different_days_same_month() -> Result<(), &'static str> {
        assert_eq!(days_between_naive((2023, 1, 1), (2023, 1, 10))?, 9);
        Ok(())
