fn reverse_words_order(s: &str) -> Result<String, std::fmt::Error> {
    let mut words: Vec<&str> = s.split(' ').collect();
    words.reverse();

    let mut result = String::new();
    let mut first_word = true;

    for word in words {
        if !first_word {
            result.push(' ')?;
        }
        result.push_str(word)?;
        first_word = false;
    }

    Ok(result)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_string() -> Result<(), std::fmt::Error> {
        let result = reverse_words_order("")?;
        assert_eq!(result, "");
        Ok(())
    }

    #[test]
    fn test_single_word() -> Result<(), std::fmt::Error> {
        let result = reverse_words_order("hello")?;
        assert_eq!(result, "hello");
        Ok(())
    }

    #[test]
    fn test_two_words() -> Result<(), std::fmt::Error> {
        let result = reverse_words_order("hello world")?;
        assert_eq!(result, "world hello");
        Ok(())
    }

    #[test]
    fn test_multiple_words() -> Result<(), std::fmt::Error> {
        let result = reverse_words_order("rust programming is fun")?;
        assert_eq!(result, "fun is programming rust");
        Ok(())
    }

    #[test]
    fn test_leading_trailing_spaces() -> Result<(), std::fmt::Error> {
        // The current implementation splits by ' ' which handles internal spaces.
        // Leading/trailing spaces would result in empty strings in the split.
        // For this task, "Words are separated by single spaces" implies no leading/trailing.
        // If they were to be handled, a trim() before split would be needed.
        let result = reverse_words_order("  leading and trailing  ")?; // This will produce "trailing and leading" with extra spaces
        assert_eq!(result, "trailing and leading"); // This is the behavior based on simple split
        Ok(())
    }

    #[test]
    fn test_multiple_spaces_between_words() -> Result<(), std::fmt::Error> {
        // Similar to leading/trailing, multiple internal spaces will create empty strings in split.
        let result = reverse_words_order("one   two")?;
        assert_eq!(result, "two one");
        Ok(())
    }
}

