fn to_pig_latin(word: &str) -> Result<String, String> {
    let first_char = word.chars().next().ok_or_else(|| "Empty word".to_string())?;

    let vowels = ['a', 'e', 'i', 'o', 'u'];
    if vowels.contains(&first_char) {
        let mut result = word.to_string();
        result.push_str("hay");
        return Ok(result);
    }

    let mut consonant_cluster_len = 0;
    for (i, c) in word.chars().enumerate() {
        if !vowels.contains(&c) {
            consonant_cluster_len = i + 1;
        } else {
            break;
        }
    }

    let (consonant_cluster, rest) = word.split_at(consonant_cluster_len);

    let mut result_string = String::new();
    result_string.push_str(rest);
    result_string.push_str(consonant_cluster);
    result_string.push_str("ay");

    Ok(result_string)
}

fn main() -> Result<(), String> {
    let word1 = "apple";
    let pig_latin1 = to_pig_latin(word1)?;
    println!("{} -> {}", word1, pig_latin1);

    let word2 = "pig";
    let pig_latin2 = to_pig_latin(word2)?;
    println!("{} -> {}", word2, pig_latin2);

    let word3 = "rhythm";
    let pig_latin3 = to_pig_latin(word3)?;
    println!("{} -> {}", word3, pig_latin3);

    let word4 = "schmuck";
    let pig_latin4 = to_pig_latin(word4)?;
    println!("{} -> {}", word4, pig_latin4);

    let word5 = "";
    let pig_latin5_result = to_pig_latin(word5);
    match pig_latin5_result {
        Ok(s) => println!("{} -> {}", word5, s),
        Err(e) => println!("Error for '{}': {}", word5, e),
    }

    let word6 = "elephant";
    let pig_latin6 = to_pig_latin(word6)?;
    println!("{} -> {}", word6, pig_latin6);

    let word7 = "yellow";
    let pig_latin7 = to_pig_latin(word7)?;
    println!("{} -> {}", word7, pig_latin7);

    Ok(())
}

