use std::error::Error;
use std::fmt;
use std::fmt::Write as FmtWrite;

/// Keeps only the `Some` values of `items`, unwrapped, preserving order.
fn flatten_options<T>(items: Vec<Option<T>>) -> Vec<T> {
    items.into_iter().flatten().collect()
}

#[derive(Debug)]
struct ParseError {
    cell: String,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "cannot read {:?} as a number", self.cell)
    }
}

impl Error for ParseError {}

#[derive(Debug)]
struct EmptyRow;

impl fmt::Display for EmptyRow {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("no readings")
    }
}

impl Error for EmptyRow {}

struct Stats {
    min: i64,
    max: i64,
    mean: f64,
}

/// An empty cell or `-` means "missing", everything else must be an integer.
fn parse_cell(cell: &str) -> Result<Option<i64>, ParseError> {
    let text = cell.trim();
    if text.is_empty() || text == "-" {
        return Ok(None);
    }
    let value = text.parse::<i64>().map_err(|_| ParseError { cell: text.to_string() })?;
    Ok(Some(value))
}

fn parse_row(line: &str) -> Result<Vec<Option<i64>>, ParseError> {
    let mut cells = Vec::new();
    for raw in line.split(',') {
        cells.push(parse_cell(raw)?);
    }
    Ok(cells)
}

fn summarize(values: &[i64]) -> Result<Stats, EmptyRow> {
    let (first, rest) = values.split_first().ok_or(EmptyRow)?;
    let mut stats = Stats { min: *first, max: *first, mean: 0.0 };
    let mut total = *first;
    for value in rest {
        stats.min = stats.min.min(*value);
        stats.max = stats.max.max(*value);
        total += *value;
    }
    stats.mean = total as f64 / values.len() as f64;
    Ok(stats)
}

fn describe_row(line: &str) -> Result<String, Box<dyn Error>> {
    let cells = parse_row(line)?;
    let width = cells.len();
    let values = flatten_options(cells);
    let mut text = String::new();
    write!(text, "{}/{} present", values.len(), width)?;
    match summarize(&values) {
        Ok(stats) => write!(text, ", mean {:.2}, span {}", stats.mean, stats.max - stats.min)?,
        Err(empty) => write!(text, ", {empty}")?,
    }
    Ok(text)
}

fn report(lines: &[&str]) -> Result<String, Box<dyn Error>> {
    let mut out = String::new();
    for (index, line) in lines.iter().enumerate() {
        let description = describe_row(line)?;
        writeln!(out, "row {index}: {description}")?;
    }
    Ok(out)
}

fn main() -> Result<(), Box<dyn Error>> {
    println!("{:?}", flatten_options(vec![Some(1), None, Some(2)]));
    println!("{:?}", flatten_options::<i32>(vec![None, None]));
    println!("{:?}", flatten_options(vec![None, Some("beta"), Some("gamma")]));

    let table = ["3, -, 9, 12", "-, -, -", "7,7,7,7"];
    print!("{}", report(&table)?);
    Ok(())
}

