        Err(e) => return Err(e.into()),
    };
    let address = match rest
        .strip_suffix('>')
        .ok_or_else(|| format!("missing '>' in {line:?}")) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let email = match parse_email(address) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(Contact {
        name: name.trim().to_string(),
        email,
    })
}

fn parse_contacts(text: &str) -> Result<Vec<Contact>, String> {
    let mut contacts = Vec::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        contacts.push(match parse_contact(line) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        });
    }
    Ok(contacts)
}

fn format_report(contacts: &[Contact]) -> Result<String, fmt::Error> {
    let mut out = String::new();
    match writeln!(out, "{} contact(s)", contacts.len()) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    for contact in contacts {
        match writeln!(out, "  {:<6} {}", contact.name, contact.email) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
    }
    let mut tlds: Vec<&str> = contacts.iter().map(|c| c.email.tld.as_str()).collect();
    tlds.sort_unstable();
    tlds.dedup();
    match write!(out, "top-level domains:") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    for tld in tlds {
        match write!(out, " .{tld}") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
    }
    match writeln!(out) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(out)
}

fn main() -> Result<(), String> {
    for candidate in ["test@example.com", "invalid-email"] {
        println!("{candidate:?} -> {}", is_valid_email(candidate));
    }
    let directory = "Alice <alice@example.com>\nBob <bob@rust-lang.org>\nCarol <carol@mail.example.com>\n";
    let contacts = match parse_contacts(directory) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let report = match format_report(&contacts).map_err(|e| e.to_string()) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    print!("{report}");
    Ok(())
}

