fn euclidean_distance_2d(x1: f64, y1: f64, x2: f62, y2: f62) -> Result<f64, String> {
    let dx_squared = (x2 - x1).powi(2);
    let dy_squared = (y2 - y1).powi(2);

    let sum_of_squares = dx_squared + dy_squared;

    if sum_of_squares < 0.0 {
        return Err("Negative sum of squares encountered, which implies an issue with input or calculation.".to_string());
    }

    let distance = sum_of_squares.sqrt();

    Ok(distance)
}

fn main() -> Result<(), String> {
    let dist1 = euclidean_distance_2d(0.0, 0.0, 3.0, 4.0)?;
    println!("Distance 1: {}", dist1);

    let dist2 = euclidean_distance_2d(1.0, 1.0, 1.0, 1.0)?;
    println!("Distance 2: {}", dist2);

    let dist3 = euclidean_distance_2d(-1.0, -1.0, 2.0, 3.0)?;
    println!("Distance 3: {}", dist3);

    let dist4 = euclidean_distance_2d(10.0, 0.0, 0.0, 10.0)?;
    println!("Distance 4: {}", dist4);

    let dist5 = euclidean_distance_2d(f64::INFINITY, 0.0, 0.0, 0.0)?;
    println!("Distance 5: {}", dist5);

    let dist6 = euclidean_distance_2d(0.0, f64::NAN, 0.0, 0.0)?;
    println!("Distance 6: {}", dist6);

    let dist7 = euclidean_distance_2d(f64::NEG_INFINITY, f64::NEG_INFINITY, f64::INFINITY, f64::INFINITY)?;
    println!("Distance 7: {}", dist7);

    Ok(())
}

