fn count_words(text: &str) -> Result<usize, Box<dyn std::error::Error>> {
    let trimmed_text = text.trim();

    if trimmed_text.is_empty() {
        return Ok(0);
    }

    let mut count = 0;
    let mut in_word = false;

    for c in trimmed_text.chars() {
        if c.is_whitespace() {
            in_word = false;
        } else if !in_word {
            count += 1;
            in_word = true;
        }
    }

    Ok(count)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let s1 = "Hello world";
    let c1 = count_words(s1)?;
    println!("'{}' has {} words", s1, c1);

    let s2 = "  One   two three  ";
    let c2 = count_words(s2)?;
    println!("'{}' has {} words", s2, c2);

    let s3 = "";
    let c3 = count_words(s3)?;
    println!("'{}' has {} words", s3, c3);

    let s4 = "   ";
    let c4 = count_words(s4)?;
    println!("'{}' has {} words", s4, c4);

    let s5 = "SingleWord";
