/// Returns the part of `path` after the last '/', or the whole string if
/// there is no '/' in it.
pub fn extract_filename(path: &str) -> &str {
    match path.rsplit_once('/') {
        Some((_, name)) => name,
        None => path,
    }
}

/// Extension of a bare file name; "dotfiles" such as `.bashrc` have none.
pub fn extension(name: &str) -> Option<&str> {
    let (stem, ext) = name.rsplit_once('.')?;
    if stem.is_empty() {
        None
    } else {
        Some(ext)
    }
}

pub struct Entry {
    pub path: String,
    pub size: u64,
}

impl Entry {
    pub fn name(&self) -> &str {
        extract_filename(&self.path)
    }
}

/// A manifest line is "<path> <size>".
fn parse_entry(line: &str) -> Result<Entry, String> {
    let (path, size) = line
        .split_once(char::is_whitespace)
        .ok_or_else(|| format!("missing size field in {:?}", line))?;
    let size = size
        .trim()
        .parse::<u64>()
        .map_err(|err| format!("bad size in {:?}: {}", line, err))?;
    Ok(Entry {
        path: path.to_string(),
        size,
    })
}

fn load_manifest(text: &str) -> Result<Vec<Entry>, String> {
    let mut entries = Vec::new();
    for line in text.lines().map(str::trim).filter(|l| !l.is_empty()) {
        entries.push(parse_entry(line)?);
    }
    Ok(entries)
}

fn largest(entries: &[Entry]) -> Option<&Entry> {
    entries.iter().max_by_key(|entry| entry.size)
}

fn report(text: &str) -> Result<String, String> {
    let entries = load_manifest(text)?;
    let biggest = largest(&entries).ok_or("manifest contains no entries")?;
    let mut out = String::new();
    for entry in &entries {
