use std::collections::HashMap;

fn roman_to_int(s: &str) -> Result<u32, &'static str> {
    let mut map = HashMap::new();
    map.insert('I', 1);
    map.insert('V', 5);
    map.insert('X', 10);

    let mut total = 0;
    let mut chars = s.chars().peekable();

    while let Some(current_char) = chars.next() {
        let current_val = *map.get(&current_char).ok_or("Invalid Roman numeral character")?;

        let next_char = chars.peek();

        if let Some(&next_char_val) = next_char {
            let next_val = *map.get(&next_char_val).ok_or("Invalid Roman numeral character")?;
            if current_val < next_val {
                return Err("Subtraction not supported for these Roman numerals");
            }
        }
        total += current_val;
    }
    Ok(total)
}

fn main() -> Result<(), &'static str> {
    let result1 = roman_to_int("VII")?;
    println!("VII: {}", result1);

    let result2 = roman_to_int("XX")?;
    println!("XX: {}", result2);

    let result3 = roman_to_int("XV")?;
    println!("XV: {}", result3);

    let result4 = roman_to_int("III")?;
    println!("III: {}", result4);

    let result_err1 = roman_to_int("IV");
    if let Err(e) = result_err1 {
        println!("Error for IV: {}", e);
    } else {
        return Err("Expected error for IV, but got success");
    }

    let result_err2 = roman_to_int("A");
    if let Err(e) = result_err2 {
        println!("Error for A: {}", e);
    } else {
        return Err("Expected error for A, but got success");
    }

    Ok(())
}

