use std::fmt;

#[derive(Clone, Copy, PartialEq)]
enum Move {
    Rock,
    Paper,
    Scissors,
}

#[derive(Clone, Copy)]
enum Outcome {
    Player1,
    Player2,
    Tie,
}

impl Outcome {
    fn label(self) -> &'static str {
        match self {
            Outcome::Player1 => "Player 1",
            Outcome::Player2 => "Player 2",
            Outcome::Tie => "Tie",
        }
    }
}

#[derive(Debug)]
enum RpsError {
    BadMove(char),
    Malformed(String),
}

impl fmt::Display for RpsError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            RpsError::BadMove(c) => write!(f, "'{}' is not a valid move", c),
            RpsError::Malformed(s) => write!(f, "cannot read round from {:?}", s),
        }
    }
}

fn parse_move(c: char) -> Result<Move, RpsError> {
    match c.to_ascii_uppercase() {
        'R' => Ok(Move::Rock),
        'P' => Ok(Move::Paper),
        'S' => Ok(Move::Scissors),
        other => Err(RpsError::BadMove(other)),
    }
}

fn judge(first: char, second: char) -> Result<Outcome, RpsError> {
    let m1 = parse_move(first)?;
    let m2 = parse_move(second)?;
    if m1 == m2 {
        return Ok(Outcome::Tie);
    }
    let beats = matches!(
        (m1, m2),
        (Move::Rock, Move::Scissors) | (Move::Paper, Move::Rock) | (Move::Scissors, Move::Paper)
    );
    Ok(if beats { Outcome::Player1 } else { Outcome::Player2 })
}

fn play_rps_round(first: char, second: char) -> String {
    match judge(first, second) {
        Ok(outcome) => outcome.label().to_string(),
        Err(e) => panic!("{}", e),
    }
}

fn single_char(field: &str) -> Result<char, RpsError> {
    let trimmed = field.trim();
    let mut chars = trimmed.chars();
    let c = chars.next().ok_or_else(|| RpsError::Malformed(field.to_string()))?;
    match chars.next() {
        Some(_) => Err(RpsError::Malformed(field.to_string())),
        None => Ok(c),
    }
}

fn parse_round(line: &str) -> Result<(char, char), RpsError> {
    let (left, right) = line.split_once(',').ok_or_else(|| RpsError::Malformed(line.to_string()))?;
    let a = single_char(left)?;
    let b = single_char(right)?;
    Ok((a, b))
}

fn play_match(input: &str) -> Result<String, RpsError> {
    let (mut p1, mut p2, mut ties) = (0u32, 0u32, 0u32);
    for line in input.lines().filter(|l| !l.trim().is_empty()) {
        let (a, b) = parse_round(line)?;
        match judge(a, b)? {
            Outcome::Player1 => p1 += 1,
            Outcome::Player2 => p2 += 1,
            Outcome::Tie => ties += 1,
        }
    }
    Ok(format!("Player 1: {}, Player 2: {}, Ties: {}", p1, p2, ties))
}

fn main() -> Result<(), RpsError> {
    println!("{}", play_rps_round('R', 'S'));
    println!("{}", play_rps_round('P', 'P'));
    println!("{}", play_match("R,S\nP,P\nS,R\nP,R\n")?);
    Ok(())
}

