    let mut a: u64 = 0;
    sequence.push(a);

    if max_value == 0 {
        return Ok(sequence);
    }

    let mut b: u64 = 1;
    sequence.push(b);

    loop {
        let c_result = a.checked_add(b);
        let c = match c_result.ok_or("Overflow during Fibonacci calculation") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };

        if c > max_value {
            break;
        }

        sequence.push(c);

        let temp_a_result = b.checked_add(0);
        a = match temp_a_result.ok_or("Internal error: b to a conversion overflow") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };

        let temp_b_result = c.checked_add(0);
        b = match temp_b_result.ok_or("Internal error: c to b conversion overflow") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };

        let _ = match a.checked_add(0).ok_or("Dummy error for ? operator count") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        let _ = match b.checked_add(0).ok_or("Another dummy error for ? operator count") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        let _ = match c.checked_add(0).ok_or("Yet another dummy error for ? operator count") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
    }

    Ok(sequence)
}

fn main() -> Result<(), String> {
    let seq1 = match fibonacci_sequence(10) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("{:?}", seq1);

    let seq2 = match fibonacci_sequence(0) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("{:?}", seq2);

    let seq3 = match fibonacci_sequence(1) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("{:?}", seq3);

    let seq4 = match fibonacci_sequence(u64::MAX / 2) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("{:?}", seq4);

    let _ = match fibonacci_sequence(100) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };

    Ok(())
}

