fn remove_duplicates_sorted(nums: &Vec<i32>) -> Result<Vec<i32>, String> {
    if nums.is_empty() {
        return Ok(Vec::new());
    }

    let mut result = Vec::with_capacity(nums.len());
    let first_element = nums.get(0).ok_or("Vector unexpectedly empty after check")?;
    result.push(*first_element);

    let mut prev = *first_element;

    for i in 1..nums.len() {
        let current = nums.get(i).ok_or("Error accessing vector element")?;
        if *current != prev {
            result.push(*current);
            prev = *current;
        }
    }

    Ok(result)
}

fn main() -> Result<(), String> {
    let test1 = vec![1, 1, 2, 3, 3, 3, 4];
    let result1 = remove_duplicates_sorted(&test1)?;
    println!("Original: {:?}, Deduplicated: {:?}", test1, result1);

    let test2 = vec![5, 5, 5];
    let result2 = remove_duplicates_sorted(&test2)?;
    println!("Original: {:?}, Deduplicated: {:?}", test2, result2);

    let test3 = vec![1, 2, 3];
    let result3 = remove_duplicates_sorted(&test3)?;
    println!("Original: {:?}, Deduplicated: {:?}", test3, result3);

    let test4 = vec![];
    let result4 = remove_duplicates_sorted(&test4)?;
    println!("Original: {:?}, Deduplicated: {:?}", test4, result4);

    let test5 = vec![7];
    let result5 = remove_duplicates_sorted(&test5)?;
    println!("Original: {:?}, Deduplicated: {:?}", test5, result5);

    Ok(())
}

