fn count_vowels(text: &str) -> usize {
    text.chars()
        .filter(|c| matches!(c.to_ascii_lowercase(), 'a' | 'e' | 'i' | 'o' | 'u'))
        .count()
}

fn parse_entry(line: &str) -> Result<(&str, &str), String> {
    let (label, text) = match line
        .split_once('=')
        .ok_or_else(|| format!("missing '=' separator in {:?}", line)) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let label = label.trim();
    if label.is_empty() {
        return Err(format!("empty label in {:?}", line));
    }
    Ok((label, text.trim()))
}

fn parse_entries(input: &str) -> Result<Vec<(&str, &str)>, String> {
    let mut entries = Vec::new();
    for line in input.lines().filter(|l| !l.trim().is_empty()) {
        entries.push(match parse_entry(line) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        });
    }
    Ok(entries)
}

fn vowel_percentage(text: &str) -> Result<usize, String> {
    let letters = text.chars().filter(|c| c.is_alphabetic()).count();
    if letters == 0 {
        return Err(format!("{:?} has no letters to measure", text));
    }
    Ok(count_vowels(text) * 100 / letters)
}

fn describe(label: &str, text: &str) -> Result<String, String> {
    let share = match vowel_percentage(text) {
