use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum CipherError {
    MissingField(&'static str),
    BadKey(ParseIntError),
    KeyOutOfRange(u32),
    UnknownOp(String),
}

impl fmt::Display for CipherError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            CipherError::MissingField(name) => write!(f, "missing field: {}", name),
            CipherError::BadKey(e) => write!(f, "key is not a number: {}", e),
            CipherError::KeyOutOfRange(n) => write!(f, "key {} is outside 0..=25", n),
            CipherError::UnknownOp(op) => write!(f, "unknown operation: {}", op),
        }
    }
}

impl From<ParseIntError> for CipherError {
    fn from(e: ParseIntError) -> Self {
        CipherError::BadKey(e)
    }
}

fn parse_key(text: &str) -> Result<u8, CipherError> {
    let value: u32 = text.trim().parse()?;
    if value > 25 {
        return Err(CipherError::KeyOutOfRange(value));
    }
    Ok(value as u8)
}

fn shift_char(c: char, key: u8) -> char {
    let base = if c.is_ascii_lowercase() {
        b'a'
    } else if c.is_ascii_uppercase() {
        b'A'
    } else {
        return c;
    };
    (base + (c as u8 - base + key % 26) % 26) as char
}

fn caesar_encrypt(text: &str, key: u8) -> String {
    text.chars().map(|c| shift_char(c, key)).collect()
}

fn caesar_decrypt(text: &str, key: u8) -> String {
    caesar_encrypt(text, (26 - key % 26) % 26)
}

fn split_command(line: &str) -> Result<(&str, &str, &str), CipherError> {
    let mut parts = line.splitn(3, ' ');
    let op = parts.next().ok_or(CipherError::MissingField("operation"))?;
    let key = parts.next().ok_or(CipherError::MissingField("key"))?;
    let text = parts.next().ok_or(CipherError::MissingField("text"))?;
    Ok((op, key, text))
}

fn run_command(line: &str) -> Result<String, CipherError> {
    let (op, key_text, text) = split_command(line)?;
    let key = parse_key(key_text)?;
    match op {
        "encrypt" => Ok(caesar_encrypt(text, key)),
        "decrypt" => Ok(caesar_decrypt(text, key)),
        other => Err(CipherError::UnknownOp(other.to_string())),
    }
}

fn process_script(script: &str) -> Result<Vec<String>, CipherError> {
    let mut results = Vec::new();
    for line in script.lines().filter(|l| !l.trim().is_empty()) {
        results.push(run_command(line.trim())?);
    }
    Ok(results)
}

fn roundtrip_matches(text: &str, key_text: &str) -> Result<bool, CipherError> {
    let key = parse_key(key_text)?;
    Ok(caesar_decrypt(&caesar_encrypt(text, key), key) == text)
}

fn main() -> Result<(), CipherError> {
    println!("{}", caesar_encrypt("abc", 1));
    println!("{}", caesar_encrypt("XYZ", 3));

    let script = "encrypt 5 Attack at dawn!\ndecrypt 5 Fyyfhp fy ifbs!";
    for line in process_script(script)? {
        println!("{}", line);
    }

    let key = parse_key(" 7 ")?;
    println!("{}", caesar_encrypt("Rust 2026", key));
    println!("roundtrip stable: {}", roundtrip_matches("Hello, World!", "13")?);
    Ok(())
}

