use std::collections::HashSet;

fn has_duplicates(values: &Vec<i32>) -> bool {
    let mut seen = HashSet::new();
    values.iter().any(|value| !seen.insert(*value))
}

fn first_duplicate(values: &Vec<i32>) -> Option<i32> {
    let mut seen = HashSet::new();
    values.iter().copied().find(|value| !seen.insert(*value))
}

fn parse_row(line: &str) -> Result<Vec<i32>, String> {
    let mut row = Vec::new();
    for token in line.split(',') {
        let text = token.trim();
        let value: i32 = text
            .parse()
            .map_err(|err| format!("cannot parse {:?}: {}", text, err))?;
        row.push(value);
    }
    Ok(row)
}

fn describe(line: &str) -> Result<String, String> {
    let row = parse_row(line)?;
    let note = match first_duplicate(&row) {
        Some(repeated) => format!("first repeated value is {}", repeated),
        None => "all elements are distinct".to_string(),
    };
    Ok(format!("{:?} -> {} ({})", row, has_duplicates(&row), note))
}

fn summarize(text: &str) -> Result<String, String> {
    let mut report = String::new();
    for line in text.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        report.push_str(&describe(trimmed)?);
        report.push('\n');
    }
    Ok(report)
}

fn require_distinct(values: &Vec<i32>) -> Result<(), String> {
    match first_duplicate(values) {
        Some(repeated) => Err(format!("{:?} repeats {}", values, repeated)),
        None => Ok(()),
    }
}

fn merge_distinct(text: &str) -> Result<Vec<i32>, String> {
    let mut merged = Vec::new();
    for line in text.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let row = parse_row(trimmed)?;
        require_distinct(&row)?;
        merged.extend(row.iter().copied());
    }
    require_distinct(&merged)?;
    Ok(merged)
}

fn main() -> Result<(), String> {
    let data = "1, 2, 3, 1\n4,5,6\n7, 7\n";
    print!("{}", summarize(data)?);
    println!("{}", describe("1, 2, 3")?);

    let merged = merge_distinct("1,2,3\n4,5,6\n")?;
    println!("merged {:?}, duplicates: {}", merged, has_duplicates(&merged));

    match merge_distinct(data) {
        Ok(values) => println!("merged {:?}", values),
        Err(err) => println!("rejected: {}", err),
    }
    Ok(())
}

