use chrono::NaiveDate;

fn days_between(
    date1: (u32, u32, u32),
    date2: (u32, u32, u32),
) -> Result<i64, chrono::ParseError> {
    let nd1 = NaiveDate::from_ymd_opt(date1.0 as i32, date1.1, date1.2).ok_or_else(|| {
        chrono::ParseError::from(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Invalid date1",
        ))
    })?;
    let nd2 = NaiveDate::from_ymd_opt(date2.0 as i32, date2.1, date2.2).ok_or_else(|| {
        chrono::ParseError::from(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Invalid date2",
        ))
    })?;

    let duration = nd2.signed_duration_since(nd1);
    duration.num_days().try_into().map_err(|e| {
        chrono::ParseError::from(std::io::Error::new(
            std::io::ErrorKind::Other,
            format!("Conversion error: {}", e),
        ))
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
