fn rotate_left(arr: &[i32], n: usize) -> Result<Vec<i32>, String> {
    if arr.is_empty() {
        return Ok(Vec::new());
    }

    let len = arr.len();
    if n >= len {
        let remainder = n % len;
        let mut rotated_vec = Vec::with_capacity(len);
        rotated_vec.extend_from_slice(&arr[remainder..]);
        rotated_vec.extend_from_slice(&arr[0..remainder]);
        return Ok(rotated_vec);
    }

    let mut rotated_vec = Vec::with_capacity(len);
    rotated_vec.extend_from_slice(&arr[n..]);
    rotated_vec.extend_from_slice(&arr[0..n]);
    Ok(rotated_vec)
}

fn test_rotate_left() -> Result<(), String> {
    let original = vec![1, 2, 3, 4, 5];
    let rotated = rotate_left(&original, 2)?;
    assert_eq!(rotated, vec![3, 4, 5, 1, 2]);

    let original2 = vec![1, 2, 3];
    let rotated2 = rotate_left(&original2, 0)?;
    assert_eq!(rotated2, vec![1, 2, 3]);

    let original3 = vec![1, 2, 3];
    let rotated3 = rotate_left(&original3, 3)?;
    assert_eq!(rotated3, vec![1, 2, 3]);

    let original4 = vec![1, 2, 3];
    let rotated4 = rotate_left(&original4, 1)?;
    assert_eq!(rotated4, vec![2, 3, 1]);

    let original5 = Vec::<i32>::new();
    let rotated5 = rotate_left(&original5, 5)?;
    assert_eq!(rotated5, Vec::<i32>::new());

    let original6 = vec![1];
    let rotated6 = rotate_left(&original6, 0)?;
    assert_eq!(rotated6, vec![1]);

    let original7 = vec![1];
    let rotated7 = rotate_left(&original7, 1)?;
    assert_eq!(rotated7, vec![1]);

    let original8 = vec![1, 2, 3, 4, 5];
    let rotated8 = rotate_left(&original8, 7)?;
    assert_eq!(rotated8, vec![3, 4, 5, 1, 2]);

    let original9 = vec![10, 20, 30, 40];
