fn is_valid_luhn(card_number: &str) -> Result<bool, Box<dyn std::error::Error>> {
    let mut sum: u32 = 0;
    let mut is_second_digit = false;

    let trimmed_number = card_number.trim();

    for c in trimmed_number.chars().rev() {
        let digit = c.to_digit(10).ok_or("Invalid character in card number")?;

        let mut current_digit = digit;
        if is_second_digit {
            current_digit *= 2;
            if current_digit > 9 {
                current_digit -= 9;
            }
        }
        sum += current_digit;
        is_second_digit = !is_second_digit;
    }

    Ok(sum % 10 == 0)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let valid_number = "79927398713";
    let invalid_number_short = "12345";
    let invalid_number_char = "123A45";
    let valid_with_space = " 79927398713 ";

    println!("Is \"{}\" valid? {}", valid_number, is_valid_luhn(valid_number)?);
    println!("Is \"{}\" valid? {}", invalid_number_short, is_valid_luhn(invalid_number_short)?);
    let result_char_invalid = is_valid_luhn(invalid_number_char);
    println!("Is \"{}\" valid? {:?}", invalid_number_char, result_char_invalid);
    println!("Is \"{}\" valid? {}", valid_with_space, is_valid_luhn(valid_with_space)?);

    let another_valid = "49927398716";
    let is_another_valid = is_valid_luhn(another_valid)?;
    println!("Is \"{}\" valid? {}", another_valid, is_another_valid);

    let a_third_test = "1234567890123452";
    let third_result = is_valid_luhn(a_third_test)?;
    println!("Is \"{}\" valid? {}", a_third_test, third_result);

    let final_test_num = "49927398717";
    let final_result = is_valid_luhn(final_test_num)?;
    println!("Is \"{}\" valid? {}", final_test_num, final_result);

    Ok(())
}

