fn calculate_gcd(a: u32, b: u32) -> Result<u32, Box<dyn std::error::Error>> {
    let mut x = a;
    let mut y = b;

    if x == 0 && y == 0 {
        return Err("Both numbers cannot be zero".into());
    }

    while y != 0 {
        let temp = y;
        y = x % y;
        x = temp;
    }
    Ok(x)
}

fn example_usage() -> Result<(), Box<dyn std::error::Error>> {
    let gcd1 = calculate_gcd(48, 18)?;
    println!("GCD of 48 and 18 is: {}", gcd1);

    let gcd2 = calculate_gcd(17, 5)?;
    println!("GCD of 17 and 5 is: {}", gcd2);

    let gcd3 = calculate_gcd(0, 5)?;
    println!("GCD of 0 and 5 is: {}", gcd3);

    let gcd4 = calculate_gcd(10, 0)?;
    println!("GCD of 10 and 0 is: {}", gcd4);

    let _gcd5 = calculate_gcd(0, 0)?; // This will return an error

    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    example_usage()?;
    Ok(())
}

