use std::env;

/// Largest row whose entries all fit in `u64`: C(68, 34) already overflows.
const MAX_ROW: u32 = 67;

/// Row `row_index` built by repeated addition, or `None` on `u64` overflow.
fn try_row(row_index: u32) -> Option<Vec<u64>> {
    let mut row: Vec<u64> = vec![1];
    for _ in 0..row_index {
        let mut next = Vec::with_capacity(row.len() + 1);
        next.push(1);
        for pair in row.windows(2) {
            next.push(pair[0].checked_add(pair[1])?);
        }
        next.push(1);
        row = next;
    }
    Some(row)
}

fn checked_row(row_index: u32) -> Result<Vec<u64>, String> {
    try_row(row_index).ok_or_else(|| format!("row {row_index} does not fit in u64"))
}

/// Elements of row `row_index` (0-indexed) of Pascal's Triangle.
pub fn pascals_triangle_row(row_index: u32) -> Vec<u64> {
    match try_row(row_index) {
        Some(row) => row,
        None => panic!("row {row_index} exceeds the range of u64"),
    }
}

fn format_row(row_index: u32) -> Result<String, String> {
    let row = checked_row(row_index)?;
    let cells: Vec<String> = row.iter().map(u64::to_string).collect();
    Ok(cells.join(" "))
}

fn row_sum(row_index: u32) -> Result<u64, String> {
    let mut total: u64 = 0;
    for value in checked_row(row_index)? {
        total = total
            .checked_add(value)
            .ok_or_else(|| format!("sum of row {row_index} overflows u64"))?;
    }
    Ok(total)
}

fn render_triangle(last_row: u32) -> Result<String, String> {
    let width = format_row(last_row)?.len();
    let mut out = String::new();
    for index in 0..=last_row {
        let line = format_row(index)?;
        out.push_str(&" ".repeat(width.saturating_sub(line.len()) / 2));
        out.push_str(&line);
        out.push('\n');
    }
    Ok(out)
}

fn parse_row_index(text: &str) -> Result<u32, String> {
    let trimmed = text.trim();
    let value: u32 = trimmed
        .parse()
        .map_err(|e| format!("invalid row index {trimmed:?}: {e}"))?;
    if value > MAX_ROW {
        return Err(format!("row {value} exceeds the supported maximum {MAX_ROW}"));
    }
    Ok(value)
}

fn main() -> Result<(), String> {
    let args: Vec<String> = env::args().skip(1).collect();
    if args.is_empty() {
        print!("{}", render_triangle(6)?);
        return Ok(());
    }
    for arg in &args {
        let index = parse_row_index(arg)?;
        println!("row {index}: {:?}", pascals_triangle_row(index));
        println!("  sum: {}", row_sum(index)?);
    }
    Ok(())
}

