use std::fmt;
use std::num::ParseFloatError;

#[derive(Debug)]
enum StatsError {
    Parse(ParseFloatError),
    LengthMismatch(usize, usize),
    Empty,
    ZeroWeight,
}

impl From<ParseFloatError> for StatsError {
    fn from(e: ParseFloatError) -> Self {
        StatsError::Parse(e)
    }
}

impl fmt::Display for StatsError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            StatsError::Parse(e) => write!(f, "bad number: {}", e),
            StatsError::LengthMismatch(v, w) => write!(f, "{} values but {} weights", v, w),
            StatsError::Empty => write!(f, "no data points"),
            StatsError::ZeroWeight => write!(f, "weights sum to zero"),
        }
    }
}

fn parse_series(text: &str) -> Result<Vec<f64>, StatsError> {
    let mut series = Vec::new();
    for field in text.split(',') {
        series.push(field.trim().parse::<f64>()?);
    }
    Ok(series)
}

fn ensure_aligned(values: &Vec<f64>, weights: &Vec<f64>) -> Result<(), StatsError> {
    if values.len() != weights.len() {
        return Err(StatsError::LengthMismatch(values.len(), weights.len()));
    }
    if values.is_empty() {
        return Err(StatsError::Empty);
    }
    Ok(())
}

fn total_weight(weights: &Vec<f64>) -> Result<f64, StatsError> {
    let total: f64 = weights.iter().sum();
    if total.abs() < f64::EPSILON {
        return Err(StatsError::ZeroWeight);
    }
    Ok(total)
}

fn checked_weighted_average(values: &Vec<f64>, weights: &Vec<f64>) -> Result<f64, StatsError> {
    ensure_aligned(values, weights)?;
    let total = total_weight(weights)?;
    let dot: f64 = values.iter().zip(weights.iter()).map(|(v, w)| v * w).sum();
    Ok(dot / total)
}

fn weighted_average(values: &Vec<f64>, weights: &Vec<f64>) -> f64 {
    match checked_weighted_average(values, weights) {
        Ok(mean) => mean,
        Err(e) => panic!("weighted_average: {}", e),
    }
}

fn weight_shares(weights: &Vec<f64>) -> Result<Vec<f64>, StatsError> {
    let total = total_weight(weights)?;
    Ok(weights.iter().map(|w| 100.0 * w / total).collect())
}

fn report_line(label: &str, values_csv: &str, weights_csv: &str) -> Result<String, StatsError> {
    let values = parse_series(values_csv)?;
    let weights = parse_series(weights_csv)?;
    ensure_aligned(&values, &weights)?;
    let shares = weight_shares(&weights)?;
    let shares_text: Vec<String> = shares.iter().map(|s| format!("{:.1}%", s)).collect();
    let mean = weighted_average(&values, &weights);
    Ok(format!("{:<8} mean = {:>8.3}  [{}]", label, mean, shares_text.join(", ")))
}

fn main() -> Result<(), StatsError> {
    let records = [
        ("equal", "10, 20", "1, 1"),
        ("skewed", "10, 20", "0.7, 0.3"),
