use std::fmt;

#[derive(Debug)]
enum DecodeError {
    BadEscape(String),
    Truncated,
    MissingEquals(String),
    NotUtf8,
}

impl fmt::Display for DecodeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DecodeError::BadEscape(s) => write!(f, "invalid escape sequence '%{}'", s),
            DecodeError::Truncated => write!(f, "percent sign at end of input"),
            DecodeError::MissingEquals(s) => write!(f, "query part '{}' has no '='", s),
            DecodeError::NotUtf8 => write!(f, "decoded bytes are not valid UTF-8"),
        }
    }
}

fn is_unreserved(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~')
}

fn url_encode_simple(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for byte in input.bytes() {
        if is_unreserved(byte) {
            out.push(byte as char);
        } else {
            out.push_str(&format!("%{:02X}", byte));
        }
    }
    out
}

fn hex_digit(c: u8) -> Option<u8> {
    let digit = (c as char).to_digit(16)?;
    Some(digit as u8)
}

fn decode_escape(pair: &[u8]) -> Result<u8, DecodeError> {
    let text = String::from_utf8_lossy(pair).into_owned();
    let hi = hex_digit(pair[0]).ok_or_else(|| DecodeError::BadEscape(text.clone()))?;
    let lo = hex_digit(pair[1]).ok_or(DecodeError::BadEscape(text))?;
    Ok(hi * 16 + lo)
}

fn url_decode(input: &str) -> Result<String, DecodeError> {
    let bytes = input.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' {
            let pair = bytes.get(i + 1..i + 3).ok_or(DecodeError::Truncated)?;
            out.push(decode_escape(pair)?);
            i += 3;
        } else {
            out.push(bytes[i]);
            i += 1;
        }
    }
    String::from_utf8(out).map_err(|_| DecodeError::NotUtf8)
}

fn parse_query(raw: &str) -> Result<Vec<(String, String)>, DecodeError> {
    let mut pairs = Vec::new();
    for part in raw.split('&').filter(|p| !p.is_empty()) {
        let (key, value) = part
            .split_once('=')
            .ok_or_else(|| DecodeError::MissingEquals(part.to_string()))?;
        let name = url_decode(key)?;
        pairs.push((name, url_decode(value)?));
    }
    Ok(pairs)
}

fn canonical_query(raw: &str) -> Result<String, DecodeError> {
    let mut pairs = parse_query(raw)?;
    pairs.sort();
    let encoded: Vec<String> = pairs
        .iter()
        .map(|(k, v)| format!("{}={}", url_encode_simple(k), url_encode_simple(v)))
        .collect();
    Ok(encoded.join("&"))
}

fn main() -> Result<(), DecodeError> {
    println!("{}", url_encode_simple("hello world"));
    println!("{}", url_encode_simple("test/path"));

    let canonical = canonical_query("q=rust+web&file=my%20notes.txt")?;
    println!("{}", canonical);
    for (key, value) in parse_query(&canonical)? {
        println!("  {} -> {}", key, value);
    }

    let path = url_decode("docs%2Fread%20me.txt")?;
    println!("{} => {}", path, url_encode_simple(&path));
    Ok(())
}

