fn hex_digit(c: char) -> Result<u8, String> {
    c.to_digit(16)
        .map(|d| d as u8)
        .ok_or_else(|| format!("Invalid hex char {}", c))
}

fn hex_to_bytes(s: &str) -> Result<Vec<u8>, String> {
    let chars: Vec<char> = s.chars().collect();
    let mut out = Vec::with_capacity(chars.len() / 2);
    for pair in chars.chunks(2) {
        let hi = hex_digit(pair[0])?;
        let second = *pair
            .get(1)
            .ok_or_else(|| format!("Odd length hex string {}", s))?;
        let lo = hex_digit(second)?;
        out.push((hi << 4) | lo);
    }
    Ok(out)
}

fn bytes_to_hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{:02X}", b)).collect()
}

fn checksum(bytes: &[u8]) -> u8 {
    bytes.iter().fold(0u8, |acc, b| acc.wrapping_add(*b))
}

fn check_name(name: &str) -> Result<(), String> {
    if name.is_empty() {
        return Err("Record name is empty".to_string());
    }
    if !name.chars().all(|c| c.is_ascii_alphanumeric()) {
        return Err(format!("Invalid record name {}", name));
    }
    Ok(())
}

fn parse_record(line: &str) -> Result<(String, Vec<u8>), String> {
    let (name, hex) = line
        .split_once(':')
        .ok_or_else(|| format!("Missing ':' in record {}", line))?;
    check_name(name)?;
    let bytes = hex_to_bytes(hex.trim())?;
    Ok((name.to_string(), bytes))
}

fn verify_record(line: &str) -> Result<String, String> {
    let (name, mut bytes) = parse_record(line)?;
    let given = bytes
        .pop()
        .ok_or_else(|| format!("Record {} carries no checksum byte", name))?;
    let computed = checksum(&bytes);
    if computed != given {
        return Err(format!(
            "Record {}: checksum {:02X} does not match {:02X}",
            name, given, computed
        ));
    }
    Ok(format!("{} -> {} ({} bytes)", name, bytes_to_hex(&bytes), bytes.len()))
}

fn encode_record(name: &str, payload: &[u8]) -> Result<String, String> {
    check_name(name)?;
    let mut bytes = payload.to_vec();
    bytes.push(checksum(payload));
    Ok(format!("{}:{}", name, bytes_to_hex(&bytes)))
}

fn main() -> Result<(), String> {
    let built = encode_record("delta", &[0x10, 0x20, 0x30])?;
    let records = ["alpha:F0A191", "beta:01020306", "gamma:FFG", built.as_str()];
    for record in records {
        match verify_record(record) {
            Ok(summary) => println!("{}", summary),
            Err(message) => println!("error: {}", message),
        }
    }
    Ok(())
}

