fn next_term(n: u64) -> Option<u64> {
    if n % 2 == 0 {
        Some(n / 2)
    } else {
        n.checked_mul(3)?.checked_add(1)
    }
}

pub fn collatz_sequence(start: u64) -> Vec<u64> {
    let mut seq = vec![start];
    let mut current = start;
    while current != 1 {
        current = next_term(current).expect("Collatz term overflowed u64");
        seq.push(current);
    }
    seq
}

fn parse_start(text: &str) -> Result<u64, String> {
    let trimmed = text.trim();
    let n: u64 = trimmed
        .parse()
        .map_err(|e| format!("'{}' is not a valid integer: {}", trimmed, e))?;
    if n == 0 {
        return Err("the start value must be a positive integer".to_string());
    }
    Ok(n)
}

fn sequence_from_text(text: &str) -> Result<Vec<u64>, String> {
    Ok(collatz_sequence(parse_start(text)?))
}

fn first_above(seq: &[u64], bound: u64) -> Option<(usize, u64)> {
    let idx = seq.iter().position(|&term| term > bound)?;
    Some((idx, seq[idx]))
}

fn format_sequence(seq: &[u64]) -> String {
    let shown: Vec<String> = if seq.len() <= 12 {
        seq.iter().map(|t| t.to_string()).collect()
    } else {
        let head = seq[..6].iter().map(|t| t.to_string());
        let tail = seq[seq.len() - 3..].iter().map(|t| t.to_string());
        head.chain(std::iter::once("...".to_string())).chain(tail).collect()
    };
    shown.join(" -> ")
}

fn summarize(text: &str) -> Result<String, String> {
    let seq = sequence_from_text(text)?;
    let mut line = format!("{}: {} terms | {}", seq[0], seq.len(), format_sequence(&seq));
    if let Some((idx, term)) = first_above(&seq, 1000) {
        line.push_str(&format!(" | first term above 1000: {} at index {}", term, idx));
    }
    Ok(line)
}

fn longest_in_range(lo_text: &str, hi_text: &str) -> Result<(u64, usize), String> {
    let lo = parse_start(lo_text)?;
    let hi = parse_start(hi_text)?;
    if lo > hi {
        return Err(format!("empty range: {} > {}", lo, hi));
    }
    let mut best = (lo, collatz_sequence(lo).len());
    for n in (lo + 1)..=hi {
        let len = collatz_sequence(n).len();
        if len > best.1 {
            best = (n, len);
        }
    }
    Ok(best)
}

fn main() -> Result<(), String> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.is_empty() {
        println!("{}", summarize("6")?);
        println!("{}", summarize("1")?);
        println!("{}", summarize("27")?);
        let (n, len) = longest_in_range("1", "10000")?;
        println!("longest chain up to 10000 starts at {} with {} terms", n, len);
    } else {
        for arg in &args {
            println!("{}", summarize(arg)?);
        }
    }
    Ok(())
}

