use std::collections::HashSet;

fn parse_csv_line(line: &str) -> Vec<String> {
    line.split(',').map(|field| field.to_string()).collect()
}

fn parse_header(line: &str) -> Result<Vec<String>, String> {
    let fields = parse_csv_line(line);
    let mut seen = HashSet::new();
    let mut header = Vec::with_capacity(fields.len());
    for field in fields {
        let name = field.trim().to_string();
        if name.is_empty() {
            return Err(format!("header `{}` contains an empty column name", line));
        }
        if !seen.insert(name.clone()) {
            return Err(format!("header `{}` repeats column `{}`", line, name));
        }
        header.push(name);
    }
    Ok(header)
}

fn field_index(header: &[String], name: &str) -> Result<usize, String> {
    header
        .iter()
        .position(|column| column == name)
        .ok_or_else(|| format!("no column named `{}`", name))
}

fn get_field<'a>(header: &[String], row: &'a [String], name: &str) -> Result<&'a str, String> {
    let index = field_index(header, name)?;
    let raw = row
        .get(index)
        .ok_or_else(|| format!("row has {} fields, need at least {}", row.len(), index + 1))?;
    Ok(raw.trim())
}

fn get_number(header: &[String], row: &[String], name: &str) -> Result<f64, String> {
    let raw = get_field(header, row, name)?;
    raw.parse::<f64>()
        .map_err(|err| format!("column `{}` holds `{}`: {}", name, raw, err))
}

fn describe_row(header: &[String], line: &str) -> Result<(String, f64), String> {
    let row = parse_csv_line(line);
    let item = get_field(header, &row, "item")?;
    let quantity = get_number(header, &row, "quantity")?;
    let price = get_number(header, &row, "price")?;
    let total = quantity * price;
    Ok((format!("{:<10} {:>5} x {:>6.2} = {:>8.2}", item, quantity, price, total), total))
}

fn summarize(text: &str) -> Result<String, String> {
    let mut lines = text.lines().filter(|line| !line.trim().is_empty());
    let header_line = lines.next().ok_or_else(|| "input has no header".to_string())?;
    let header = parse_header(header_line)?;
    let mut report = String::new();
    let mut grand_total = 0.0;
    for line in lines {
        let (rendered, total) = describe_row(&header, line)?;
        report.push_str(&rendered);
        report.push('\n');
        grand_total += total;
    }
    report.push_str(&format!("{:<10} {:>25.2}", "TOTAL", grand_total));
    Ok(report)
}

fn main() -> Result<(), String> {
    let data = "item,quantity,price\n\
                apple,3,0.50\n\
                banana,6,0.25\n\
                cherry,12,0.10\n";
    println!("{}", summarize(data)?);
    let fields = parse_csv_line("one,\"two, three\",four");
    println!("{:?}", fields);
    Ok(())
}

