use std::error::Error;
use std::fmt::{self, Write as _};

#[derive(Debug)]
enum EntryError {
    MissingSeparator(usize),
    EmptyLabel(usize),
    EmptyText(usize),
    Format(fmt::Error),
}

impl fmt::Display for EntryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            EntryError::MissingSeparator(n) => write!(f, "line {n}: expected 'label: text'"),
            EntryError::EmptyLabel(n) => write!(f, "line {n}: label is empty"),
            EntryError::EmptyText(n) => write!(f, "line {n}: text is empty"),
            EntryError::Format(e) => write!(f, "report formatting failed: {e}"),
        }
    }
}

impl Error for EntryError {}

impl From<fmt::Error> for EntryError {
    fn from(e: fmt::Error) -> Self {
        EntryError::Format(e)
    }
}

pub fn is_palindrome_case_sensitive(s: &str) -> bool {
    let chars: Vec<char> = s.chars().collect();
    chars.iter().eq(chars.iter().rev())
}

struct Entry {
    label: String,
    text: String,
}

fn non_empty(s: &str) -> Option<&str> {
    let trimmed = s.trim();
    if trimmed.is_empty() {
        None
    } else {
        Some(trimmed)
    }
}

fn parse_entry(number: usize, line: &str) -> Result<Entry, EntryError> {
    let (raw_label, raw_text) = line.split_once(':').ok_or(EntryError::MissingSeparator(number))?;
    let label = non_empty(raw_label).ok_or(EntryError::EmptyLabel(number))?;
    let text = non_empty(raw_text).ok_or(EntryError::EmptyText(number))?;
    Ok(Entry { label: label.to_string(), text: text.to_string() })
}

fn parse_entries(input: &str) -> Result<Vec<Entry>, EntryError> {
    let mut entries = Vec::new();
    for (index, line) in input.lines().enumerate().filter(|(_, l)| !l.trim().is_empty()) {
        entries.push(parse_entry(index + 1, line)?);
    }
    Ok(entries)
}

fn summary(entries: &[Entry]) -> Option<String> {
    entries
        .iter()
        .filter(|e| is_palindrome_case_sensitive(&e.text))
        .max_by_key(|e| e.text.chars().count())
        .map(|best| {
            format!(
                "longest palindrome: {} (\"{}\", {} chars)",
                best.label,
                best.text,
                best.text.chars().count()
            )
        })
}

fn build_report(entries: &[Entry]) -> Result<String, EntryError> {
    let mut out = String::new();
    writeln!(out, "{:<10} {:>7}  {}", "LABEL", "PALIN?", "TEXT")?;
    for entry in entries {
        let verdict = is_palindrome_case_sensitive(&entry.text);
        writeln!(out, "{:<10} {:>7}  {}", entry.label, verdict, entry.text)?;
    }
    match summary(entries) {
        Some(line) => writeln!(out, "{line}")?,
        None => writeln!(out, "no case-sensitive palindromes found")?,
    }
    Ok(out)
}

fn main() -> Result<(), Box<dyn Error>> {
    let input = "\
first: madam
second: Madam
third: racecar
fourth: step on no pets
fifth: rust";
    let entries = parse_entries(input)?;
    print!("{}", build_report(&entries)?);
    Ok(())
}

